export default [{"id":207,"question":"ما الحدّ الأدنى من العبادة التي بدونها لا يُؤدي المخلوقُ غرضَ الخالق من قوله تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]؟","title":"ما الحد الأدنى للقيام بواجب العبادة لله تعالى؟","answer":"الجواب: الحد الأدنى أداء الفرائض وترك المحارم، فإذا أدَّى الفرائض وترك المحارم فلا شيء عليه، ويُسمَّى: مُقتصدًا، ويكون من الأبرار. وإن زاد فأدَّى المُستحبَّات وابتعد عن المكروهات؛ صار من السَّابقين المُقرَّبين، صار من الطبقة العليا.\nوالطبقات ثلاث:\nطبقة العُصاة: وهم الظَّالمون لأنفسهم.\nوطبقة المُقتصدين الأبرار: وهم الذين أدّوا الفرائض وتركوا المحارم فقط.\nوالطبقة الثالثة الطبقة العليا، وهي طبقة السَّابقين المُقرَّبين من الرسل وأتباعهم: الذين سارعوا إلى الخيرات، فأدّوا الفرائض وتنافسوا في أنواع الخير، وتركوا المحارم، وابتعدوا عن المكروهات والمُشتبهات، فهؤلاء هم الطبقة العُليا.","link":"https://binbaz.org.sa/fatwas/3982/ما-الحد-الادنى-للقيام-بواجب-العبادة-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0214.mp3","categories":["الإسلام والإيمان"]},{"id":680,"question":"من قال بأن القوة في المؤمن القوي تدخل في قوة البدن؟","title":"ما القوة المحمودة في المؤمن؟","answer":"الجواب: لا، ما هو بالبدن وأيش يبغى بالبدن؟! القوة قوة العمل، لو كان أفضل من الفيل ولكن ما يأمر ولا ينهى؛ فهو ما يسمى قويًّا؛ يسمى ضعيفًا.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6720/ما-القوة-المحمودة-في-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/maram247 - 01 -  Start.mp3","categories":["الإسلام والإيمان"]},{"id":752,"question":"إن أستاذنا في المراحل الأولى علمنا أن كل مؤمنٍ مسلم، وليس العكس، فهل هذا صحيح؟","title":"ما صحة أن كل مؤمن مسلم وليس العكس؟","answer":"الجواب: نعم، كل مؤمن مسلم؛ لأن الإيمان تمام الطاعة: أن يؤدي ما أوجب الله، ويدع ما حرم الله، ويسمى: مؤمنًا، فهو أكمل من المسلم المطلق، وإذا كان المسلم قد أدى الواجبات سُمّي: مسلمًا ومؤمنًا جميعًا، وإذا كان عنده نقصٌ ومعاصٍ قيل له: مسلم، ولم يقل له: مؤمن، ويجوز أن يقال: مؤمن ناقص الإيمان، أو يقال: مؤمن عاصٍ، لكن إذا قيل: مؤمن وأطلق فإنما يقال هذا في حق المستقيم المعروف بطاعة الله ورسوله وترك ما نهى الله عنه ورسوله، فيقال له: مؤمن. وهذا معنى قول: \"كل مؤمن مسلم، ولا ينعكس\"؛ لأن الإسلام أوسع من جهة ذاته، فيعمّ العاصي، ويعم المستقيم، يقال له: مسلم ولو كان عاصيًا، كالعاقِّ، والزاني، والسارق، يُسمَّى: مسلمًا إذا كان مُوحِّدًا لله، مؤمنًا بالله، ولكنه وقع في المعصية ولم يستحلّها، ولكن غلبه الشيطان والهوى ففعلها غير مُستحلٍّ لها: فزنى، أو سرق، أو عقَّ والديه، أو أحدَهما، أو اغتاب الناس، أو نَمَّ، أو أكل الربا، أو ما أشبه من المعاصي، هذا يكون مسلمًا، وأهل السنة يقولون له: مسلم، ولا يُطلقون عليه: مؤمنًا، ولكن إذا قيل: مؤمن فلا بأس أن يقال: مؤمن، لكن يُقيد: مؤمن ناقص الإيمان، مؤمن ضعيف الإيمان، مؤمن عاصٍ، هذا يُقال أيضًا له، لكن المؤمن عند الإطلاق هو المستقيم.","link":"https://binbaz.org.sa/fatwas/20642/ما-صحة-ان-كل-مومن-مسلم-وليس-العكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0565كل مؤمناً مسلم وليس العكس فهل هذا صحيح؟ ابن باز فتاوى المحاضرات.mp3","categories":["الإسلام والإيمان"]},{"id":920,"question":"هل خلاف مُرجئة الفقهاء خلافٌ في اللفظ فقط؟","title":"هل خلاف مُرجئة الفقهاء خلافٌ لفظي فقط؟","answer":"الجواب: الصواب أنه ليس لفظيًّا، وإن قال بعضُهم أنه لفظي، بل هو حقيقي معنوي؛ لأنا إذا قلنا: \"العمل ليس من الإيمان\" يلزم على هذا أنه إذا مات على قولٍ وعقيدةٍ من دون عملٍ أنه كامل الإيمان، وكامل الإيمان يدخل الجنة. ومعلومٌ أنَّ مَن مات على غير العمل ليس بكامل الإيمان، بل هو مُتوعَّدٌ بالنار بتركه الزكاة، بتركه الحج، بتركه الصيام، فيكون ناقص الإيمان، ضعيف الإيمان، مُتعرِّضًا للوعيد.\nفقول أهل السنة الذين هم عامَّة الفقهاء، وهم أصحاب النبي ﷺ وأتباعهم: أنه قولٌ وعملٌ، يزيد وينقص، خلافًا للمُرجئة بجميع أصنافهم.","link":"https://binbaz.org.sa/fatwas/20964/هل-خلاف-مرجىة-الفقهاء-خلاف-لفظي-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0760هل الخلاف مرجئة الفقهاء خلاف في اللفظ فقط؟ ابن باز فتاوى المحاضرات.mp3","categories":["الإسلام والإيمان"]},{"id":921,"question":"ما رأيكم يا فضيلة الشيخ فيمَن يقول أن الإيمان اعتقادٌ فقط، ولا يضرُّ مع الإيمان شيءٌ؟","title":"حكم قول \"الإيمان اعتقادٌ ولا يضرُّ معه شيءٌ\"","answer":"الجواب: هذا قول باطل، وهذا قول جماعةٍ من المرجئة، يُسمّون: المرجئة، وهم الذين أرجؤوا الأعمال والأقوال وأخَّروها، فمعنى هذا أنَّ مَن اعتقد الحقَّ ولم يعمل يكون مؤمنًا، ولو سبَّ الله ورسوله، ولو أشرك بالله، ولو كفر به، هذا من أبطل الباطل. فلا بدّ من الإيمان والعمل، يؤمن بالله ويعبده وحده، ولا يعبد معه سواه، يؤمن بالصلاة ويُؤديها، يؤمن بالزكاة ويُؤديها، إلى غير ذلك، لا بدّ من إيمانٍ معه قولٌ وعملٌ.","link":"https://binbaz.org.sa/fatwas/20963/حكم-قول-الايمان-اعتقاد-ولا-يضر-معه-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0759ما رأيكم فيمن يقول أن الإيمان اعتقاد فقط ولا يضر الإيمان شيء ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الإسلام والإيمان"]},{"id":930,"question":"يقول السائل: كيف نؤمن بالله دون أن نراه بأعيننا، ودون أن نلمسه بأيدينا؟ نسأل الله العافية.","title":"ما الرد على قول: كيف نؤمن بالله ولا نراه؟","answer":"الجواب: هذا من الإيمان بالغيب: الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ [البقرة:3]، فتؤمن بالله، وقد رأيت آياته، أنت من آياته، أنت مخلوقٌ من آياته، الذي أعطاك السمع والبصر، والعقل والجوارح، وخلق الماء، وخلق لك هذه النعم، هذه آياته الدالة عليه، \"في كل شيءٍ له آية تدل على أنه واحد\"، وأنت لم تُخلق عبثًا، وآيات الله لا تُحصى: من أنهارٍ، وبحارٍ، وجبالٍ، وسماء، وأرض، وغير ذلك، وأنت من آياته، كما قال : وَفِي الْأَرْضِ آيَاتٌ لِلْمُوقِنِينَ ۝ وَفِي أَنْفُسِكُمْ أَفَلَا تُبْصِرُونَ [الذاريات:20، 21].\nثم أنت تؤمن بالجنة والنار ولم ترهما أيضًا، وتؤمن بالجن ولم تر الجن، فالله أخبرك عنهم، وتؤمن بعقلك وأنت ما ترى عقلك، يعني: أنت ما عندك عقل، ما ترى عقلك، فلستَ بعاقلٍ، أنت لا ترى العقل، فلست بعاقلٍ حينئذٍ، تكون مجنونًا، وأنت لك قلبٌ ولم تره، ولك أشياء أخرى داخلية لم ترها.\nفالمقصود أن العلم يكون بالرؤية، ويكون بالخبر اليقين، ويكون بالملامسة، ويكون بالشم، ويكون بالنظر، ويكون بالسماع، طرق العلم كثيرة، ما هو فقط بمجرد اللمس، اللمس واحدٌ من الطرق، ومن أعظمها، بل أعظمها وأوسعها العلم بالخبر، أنت تعلم أن في الدنيا بلادًا يُقال لها: أمريكا، وأنت ما زرتها، تعلمها يقينًا بالأخبار والإذاعات وغير ذلك، تعلم أنَّ في الدنيا خلفاء مضوا، والنبي محمد ﷺ مضى، وأنت لم تحضر ذلك، بالأدلة، بالأخبار، تعلم أنَّ في الدنيا أنهارًا مُعينة، وحيوانات معينة، وبحارًا معينة، بالخبر، لا بالرؤية، لم ترها، وتعلم أن في الدنيا مدنًا كثيرةً لم ترها، لكن بالخبر، وهذا شيءٌ لا ينتهي، لا حصر له.","link":"https://binbaz.org.sa/fatwas/20983/ما-الرد-على-قول-كيف-نومن-بالله-ولا-نراه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0779يقول السائل كيف نؤمن بالله دون أن نرواه بأعيننا ودون أن نلمسه بأيدينا؟ ابن باز فتاوى المحاضرات.mp3","categories":["الإسلام والإيمان"]},{"id":942,"question":"ما معنى قول الصحابي: \"كنا نُؤتى الإيمان قبل القرآن\"؟","title":"ما معنى: \"كنا نُؤتى الإيمان قبل القرآن\"؟","answer":"الجواب: معناه: الإيمان بالله، يعني: الإيمان بالله وتوحيده، فهم يعلمون ويدعوهم النبيُّ ﷺ ويُؤمنون بالله ورسوله قبل أن يتعلَّموا، قبل أن يقرؤوا القرآن، فإن قول \"لا إله إلا الله\" هذا هو مبدأ الإيمان، النبيُّ يقول لهم: قولوا: لا إله إلا الله تُفْلِحوا ويدعوهم إلى هذا، ويعلم مَن جاء مسلمًا حتى يقول: \"لا إله إلا الله\"، ثم يتعلم القرآنَ بعد ذلك، يتعلم ما تيسر منه: كالفاتحة وما تيسر معها.","link":"https://binbaz.org.sa/fatwas/20971/ما-معنى-كنا-نوتى-الايمان-قبل-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0767ما معنى قول الصحابي كنا نؤتى بالإيمان قبل القرآن؟ ابن باز فتاوى المحاضرات.mp3","categories":["الإسلام والإيمان"]},{"id":2717,"question":"هل صحيح أن رابعة العدوية قالت: إني أعبد الله محبة لذاته، لا رجاءً لجنته ولا خوفًا من ناره؟","title":"حكم ما نُسِب رابعة: أعبد الله مَحَبَّةً لا للجنة","answer":"الجواب: يُحكى عنها هذا، وهذا مِن جهلها إن صح عنها، هذا مِن الجهل، الرسل عبدوا الله وخافوا من عذابه ورجوا رحمته، وهم الرسل عليهم الصلاة والسلام، لكن لو صح عنها هذا يدل على جهلها وأنها عابدة جاهلة؛ لأن الله يقول في حق الرسل والأنبياء والأخيار إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا [الأنبياء:90]، ويقول سبحانه: وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ [الرحمن:46]، ويقول: فَمَنْ كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا [الكهف:110]، وقال تعالى: أُولَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ [الإسراء:57] هكذا أولياء الله من الرسل والأخيار يعبدونه إخلاصًا له ومحبة ورجاءً وخوفًا جميعًا، الذي ما يخاف الله لا خير فيه، لا دين له.","link":"https://binbaz.org.sa/fatwas/22860/حكم-ما-نسب-رابعة-اعبد-الله-محبة-لا-للجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول رابعة العدوية إني أعبد الله محبة لذاته لا رجاء لجنته..mp3","categories":["الإسلام والإيمان"]},{"id":3303,"question":"الإيمان عند المرجئة لا ينقص؟","title":"معنى الإيمان عند المرجئة","answer":"الجواب: الإيمان عندهم قول وتصديق بس، ما فيه عمل عندهم.","link":"https://binbaz.org.sa/fatwas/23468/معنى-الايمان-عند-المرجىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإيمان عند المرجئة.mp3","categories":["الإسلام والإيمان"]},{"id":3305,"question":"المقصود بالفرائض، والشرائع، والحدود، والسُّنن (في قول عمر رضي الله عنه: إنَّ للإيمانِ فرائضَ وشرائعَ وحدودًا وسُننًا )؟","title":"معنى الفرائض والشرائع والحدود والسُّنن","answer":"الجواب: مثل ما قال عمر  : فرائض، شرائع، حدود، وسنن، كلها موجودة في القرآن والسنة، حدود: كحد الزنا، وحد الشرب، وحد ما شرعه الله، وحد ما نهى الله عنه، وشرائع: من صلاة وغيرها، وفرائض معروفة، وسنن معروفة.","link":"https://binbaz.org.sa/fatwas/23470/معنى-الفراىض-والشراىع-والحدود-والسنن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إن للإيمان فرائض، وشرائع، وحدودا، وسننا.mp3","categories":["الإسلام والإيمان"]},{"id":3306,"question":"من ذهب إلى أن أداء بعض العبادات، ومنها بعض أركان الإسلام، ليس شرطًا في صحة الإيمان، إنما هو لازمٌ شرط كمال؟","title":"هل أداء العبادات شَرْطٌ في صحة الإيمان؟","answer":"الجواب: هذا فيه تفصيل؛ الواجبات من تمام الإيمان، وترك المحرمات من تمام الإيمان؛ لكن ليس كل واجب يَكْفُرُ بتركه، وليس كل محرم يَكْفُرُ بفعله، هذا قول الخوارج. أهل السنة والجماعة لهم تفصيل بما يعرف من باب حكم المرتد، فالزاني: فاسق إن لم يستحل الزنا، ينقص إيمانه، وشارب الخمر: فاسق ينقص إيمانه ولا يرتد إلا إذا استحله، إذا استحل الزنا قال إنه حلال كَفَر، أو قال شرب الخمر حلال كَفَر، خلافًا للخوارج، وهكذا ترك الزكاة معصية كبيرة ولكن لا يكفر بذلك حتى يستحل ذلك، كذلك لو أفطر في رمضان عامدًا ما يكفر، يكون عاصيًا عند أهل السنة والجماعة.  بخلاف ترك الصلاة: محل خلاف بين العلماء إذا لم يجحد وجوبها: هل يكفر أو ما يكفر بتركها؟ على قولين؛ وأصحها أنه يكفر بتركها وحدها خاصة ولو لم يجحد الوجوب، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23471/هل-اداء-العبادات-شرط-في-صحة-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل أداء العبادات شرط في صحة الإيمان أو شرط كمال.mp3","categories":["الإسلام والإيمان"]},{"id":3330,"question":"الرد على المرجئة...؟","title":"كيف يكون الرد على المرجئة في الإيمان؟","answer":"الجواب: العمل نوع من الإيمان، يزيد وينقص، الفسوق ينقصه، القتال ينقصه، والملاحاة والشتم والشحناء تنقصه.","link":"https://binbaz.org.sa/fatwas/23496/كيف-يكون-الرد-على-المرجىة-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرد على المرجئة في الإيمان.mp3","categories":["الإسلام والإيمان"]},{"id":3333,"question":"(معنى) الإسلام والإيمان إذا اجتمعا افترقا، وإذا افترقا اجتمعا؟","title":"ما الفرق بين الإسلام والإيمان عند الإطلاق؟","answer":"الجواب: المعنى واحد، الإيمان هو الإسلام، والإسلام هو الإيمان عند الإطلاق، وإذا اقترنا فالإسلام: الأعمال الظاهرة، والإيمان: الأعمال الباطنة: إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ [آل عمران: 19] يدخل فيه الإيمان و الإيمان بضع وسبعون شعبة يدخل فيه الإسلام.","link":"https://binbaz.org.sa/fatwas/23499/ما-الفرق-بين-الاسلام-والايمان-عند-الاطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الإسلام والإيمان عند الإطلاق.mp3","categories":["الإسلام والإيمان"]},{"id":3351,"question":"إذا اجتمع الإسلام والإيمان افترقا؟","title":"ما معنى أن الإسلام والإيمان إذا اجتمعا افترقا","answer":"الجواب: نعم، عند أهل السنة إذا اجتمعا افترقا، كما في حديث جبرائيل، إذا اجتمع الإسلام والإيمان: فالإسلام الأعمال الظاهرة، والإيمان ما يتعلق بالقلوب، وإذا انفرد أحدهما دخل فيه الآخر كما في حديث وفد عبد القيس، وأشباهه، وكما في قوله جل علا: قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا ولَكِنْ قُولُوا أَسْلَمْنَا [الحجرات:14] يعني أظهرنا دين الإسلام.","link":"https://binbaz.org.sa/fatwas/23517/ما-معنى-ان-الاسلام-والايمان-اذا-اجتمعا-افترقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإسلام والإيمان إذا اجتمعا افترقا.mp3","categories":["الإسلام والإيمان"]},{"id":3353,"question":"من قال: أن عدم إدخال العمل في مسمى الإيمان من باب الخلاف اللفظي؛ لأن الثمرة..؟","title":"ما الحق في إدخال العمل في مسمى الإيمان؟","answer":"الجواب: لا، غلط، هذا ما هو بلفظي، بل حقيقي.","link":"https://binbaz.org.sa/fatwas/23519/ما-الحق-في-ادخال-العمل-في-مسمى-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حقيقة الخلاف في إدخال العمل في مسمى الإيمان.mp3","categories":["الإسلام والإيمان"]},{"id":3355,"question":"حقيقة الإرجاء في الإيمان؟","title":"ما حقيقة الإرجاء في الإيمان؟","answer":"الجواب: بعض أهل العلم يقولون: العمل لا يدخل في مسمى الإيمان، الإيمان قول فقط، أو قول مع معرفة. وهذا قول ضعيف، يقوله المرجئة.","link":"https://binbaz.org.sa/fatwas/23521/ما-حقيقة-الارجاء-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حقيقة الإرجاء في الإيمان.mp3","categories":["الإسلام والإيمان"]},{"id":4745,"question":"قول المُرجئة: لا يضرُّ مع الإيمان ذنبٌ؟","title":"ما صحة وحكم قول «لا يضرُّ مع الإيمان ذنبٌ»؟","answer":"أقوال باطلة على كل حالٍ، لكن هل ينقل من دائرة الإسلام أم لا؟ هذا محل البحث، وإلا فقولهم باطل.","link":"https://binbaz.org.sa/fatwas/25080/ما-صحة-وحكم-قول-لا-يضر-مع-الايمان-ذنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول المُرجئة لا يضرُّ مع الإيمان ذنبٌ.mp3","categories":["الإسلام والإيمان"]},{"id":4746,"question":"مَن آمن بقلبه ولسانه ولم يعمل بجوارحه؟","title":"حكم مَن آمن بقلبه ولسانه ولم يعمل بجوارحه","answer":"هذا محل خلافٍ بين العلماء، فمَن قال: إنَّ ترك الصلاة كفر، يقول: هو مخلَّد في النار، ومَن قال: إنه كفر أصغر، يكون حكمه حكم سائر الكبائر؛ تحت المشيئة.","link":"https://binbaz.org.sa/fatwas/25081/حكم-من-امن-بقلبه-ولسانه-ولم-يعمل-بجوارحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مَن آمن بقلبه ولسانه ولم يعمل بجوارحه.mp3","categories":["الإسلام والإيمان"]},{"id":4747,"question":"هل يكون مُسلمًا ولا يُقال له: مؤمن؟","title":"هل كل مسلمٍ مؤمن أو العكس؟","answer":"خلاف بين أهل السنة والجماعة؛ لأنَّ المسلم أعمُّ من المؤمن، والمؤمن أخصّ، فالإطلاق إذا أُطلق المسلمُ عمَّ الجميع: المسلمين والمؤمنين والمحسنين، ولكن قد ينفرد المسلمُ بوصف الإسلام دون الإيمان عند المدح، إذا كان من العُصاة يُقال: مسلم، وليس بمؤمن الإيمان الكامل، ولكن الأولى في مثل هذا أن يُقال: مؤمن ناقص الإيمان، أو مؤمن فاسق، أو مؤمن بإيمانه، فاسق بكبيرته، كما ذكر أبو العباس في \"العقيدة الواسطية\"؛ لأنَّ مقام المدح بالإيمان مقام عظيم، والله فصَّل بينهما فقال: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ [الأحزاب:35]، هذا عند مقام التَّفصيل: لا يزني الزاني حين يزني وهو مؤمن يعني: بل هو مسلم، ليس بمؤمنٍ الإيمان الكامل، الإيمان الذي يستحق أهله المدح الكامل، فلا بدَّ من الجمع بين النصوص بما يُؤلِّف بينها ويُوضِّح معناها.","link":"https://binbaz.org.sa/fatwas/25084/هل-كل-مسلم-مومن-او-العكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كل مسلمٍ مؤمن أو العكس.mp3","categories":["الإسلام والإيمان"]},{"id":5109,"question":"السلام عليكم ورحمة الله وبركاته: أبلغك يا شيخ أني أحبك في الله، وأبلغك سلام والدي، أما سؤالي: وهو أن كثيرًا من الناس يخطئون في فهم أن الدين وسط، ويقولون نصلي ونصوم ونفعل جميع الواجبات ونرتكب بعض المعاصي مثل سماع الأغاني وغيرها من الصغائر، فما رأيكم بهذا القول؟","title":"حكم زَعْم أن مِنْ وسطية الدين فعل بعض المعاصي","answer":"الجواب: أولاً: أحبك الله الذي أحببتنا له، فالتحاب في الله من أفضل القربات، يقول النبي ﷺ: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا عليه وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليا ففاضت عيناه ويقول عليه الصلاة والسلام يقول الله يوم القيامة: أين المتحابون بجلالي  اليوم أظلهم في ظلي يوم لا ظل إلا ظلي ويقول ﷺ: ثلاث من كن فيه وجد بهن حلاوة الإيمان: أن يكون الله ورسوله أحب إليه مما سواهما، وأن يحب المرء لا يحبه إلا لله، وأن يكره أن يعود في الكفر بعد إذ أنقذه الله منه كما يكره أن يقذف في النار، وعلى والدك السلام أيضًا. أما ما يتعلق بزعم بعض الناس أن من الوسط أن يتعاطى المعاصي؛ فهذا غلط وجهل أو جرأة على الله وإقدام على محرم، فليس الوسط الميل إلى التفريط والجفاء أو إلى الغلو والزيادة، لا، الوسط لزوم الحق وعدم الزيادة والنقص، وتعاطي المعاصي من الجفاء وليس من الوسط، والانحراف إلى الطرف الثاني وهو الجفاء والتفريط. فالواجب لزوم الحق والحذر مما حرم الله من سماع الأغاني، والملاهي، والغيبة، والنميمة، وما حرم الله من الكلام، كما يجب الحذر مما حرم الله من الأفعال، هذا هو الإسلام وهو الحق؛ أن تلزم الحق وأن تبتعد عن الطرفين طرف الجفاء وطرف الإفراط، رزق الله الجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/30017/حكم-زعم-ان-من-وسطية-الدين-فعل-بعض-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 36.mp3","categories":["الإسلام والإيمان"]},{"id":5128,"question":"سائل يقول: هل الدين خاصٌّ بشعائر معينة، أم أنَّه شاملٌ لكل أمور الحياة؟ وما الحكم فيمن يقول: إنَّ الدين خاصٌّ بالمسجد، أو لا يدخل في المعاملات والسياسة وما شابه ذلك؟","title":"ما حكم من يزعم أن الدين في المسجد فقط؟","answer":"الجواب: الدين عام، يعمُّ المسجد والبيت والدكان، ويعم السفر والحضر، ويعم السيارة والبعير، ويعم كلَّ شيء: يَا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً [البقرة:208]، أي: في الإسلام كله، فعلى العبد أن يتَّقي الله في كلِّ شيءٍ، وأن يُسلم وجهه إلى الله في كل شيءٍ، ليس في المسجد فقط، بل في المسجد، وفي البيت، مع أهله، ومع ضيوفه، ومع جيرانه، وفي الأسواق مع إخوانه في محلِّ البيع والشِّراء، عليه أن يبيع كما شرع الله، ويحذر الرِّبا، ويحذر الكذب، ويحذر الخيانة، ويحذر الغش، وهكذا في جميع أحواله. الدِّين عامٌّ في كلِّ شيءٍ، وهو معك في كل مكانٍ: في بيتك، في دكانك، في سفرك، في إقامتك، في الشدة، في الرخاء، عليك أن تلتزم بالدِّين، ليس فقط في المسجد، فهذا يقوله الضَّالون، يقوله العلمانيون، دُعاة الضَّلالة والإلحاد. الدِّين معك في كلِّ شيءٍ، فعليك أن تلتزم بدين الله في كل شيءٍ، وأن تستقيم على دين الله في كل شيء، فالمسلم يلتزم بدين الله، ويستقيم على أمر الله في جميع الأمور، لا يختص بالبيت، ولا بالمسجد، ولا بالسفر، ولا بالحضر، بل في جميع الأشياء عليك أن تطيع الله وتُؤدي فرائضه، وتنتهي عن محارمه، وتقف عند حدوده أينما كنتَ: في بيتك، أو في الجو، أو في البحر، أو في السوق، أو في أي مكانٍ.","link":"https://binbaz.org.sa/fatwas/30042/ما-حكم-من-يزعم-ان-الدين-في-المسجد-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 63.mp3","categories":["الإسلام والإيمان"]},{"id":5221,"question":"السائل يقول: ما الحدّ الأدنى من العبادة التي بدونها لا يُؤدي المخلوقُ غرضَ الخالق من قوله تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]؟","title":"ما الحدّ الأدنى من العبادة الذي يُرضِي الخالق؟","answer":"الجواب: الحد الأدنى أداء الفرائض وترك المحارم، فإذا أدَّى الفرائض وترك المحارم فلا شيء عليه، ويُسمَّى: مُقتصدًا، ويكون من الأبرار، وإن زاد فأدَّى المُستحبَّات وابتعد عن المكروهات صار من السَّابقين المُقرَّبين، صار من الطبقة العليا. والطبقات ثلاث: طبقة العُصاة: وهم الظَّالمون لأنفسهم. وطبقة المُقتصدين الأبرار: وهم الذين أدّوا الفرائض وتركوا المحارم فقط. والطبقة الثالثة: الطبقة العليا، وهي طبقة السَّابقين المُقرَّبين من الرسل وأتباعهم: الذين سارعوا إلى الخيرات، فأدّوا الفرائض وتنافسوا في أنواع الخير، وتركوا المحارم وابتعدوا عن المكروهات والمُشتبهات، فهؤلاء هم الطبقة العُليا.","link":"https://binbaz.org.sa/fatwas/30165/ما-الحد-الادنى-من-العبادة-الذي-يرضي-الخالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 214.mp3","categories":["الإسلام والإيمان"]},{"id":5351,"question":"قول شيخ الإسلام: الخلاف بيننا وبين الأحناف لفظي؟","title":"هل الخلاف بين أهل السنة والأحناف في الإيمان لفظي؟","answer":"الجواب: ما رأيتُه لشيخ الإسلام، هذا أظنّ ذكره ابنُ أبي العزّ: إما عن نفسه، أو عن غيره، وليس بصحيحٍ، ليس بلفظيٍّ، بل حقيقة، إذا قالوا: بالإيمان الكامل يستحقّ الجنة، فهو خلاف، ما هو بلفظي، أما إذا قالوا: أنه ما يستحقّ الجنة، وأنه موقوفٌ، وأنَّ إيمانه ليس بكاملٍ، وعلى خطرٍ، هذا يصير لفظيًّا، لكن إذا قالوا: ليس من الإيمانٍ، وأنه كمال، مجرد كمال، هذا غلط عظيم.[1]","link":"https://binbaz.org.sa/fatwas/31046/هل-الخلاف-بين-اهل-السنة-والاحناف-في-الايمان-لفظي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 006.mp3","categories":["الإسلام والإيمان"]},{"id":5480,"question":"الاعتقاد هل يكون بالقول أو العمل؟","title":"هل اعتقاد القلب يكون بالقول أو بالعمل؟","answer":"الجواب: اعتقاده: قول القلب، وعمله: الخوف والرجاء والمحبة، ونحو ذلك، والتصديق هو القول.[1]","link":"https://binbaz.org.sa/fatwas/31376/هل-اعتقاد-القلب-يكون-بالقول-او-بالعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 005.mp3","categories":["الإسلام والإيمان"]},{"id":5481,"question":"ما قولك في قول المُؤلف: أنَّ الإيمان في لغة العرب هو مجرد التَّصديق؟","title":"ما حكم القول بأنَّ الإيمان لغةً هو التَّصديق؟","answer":"الجواب: هذا أصله، لكن التَّصديق يكون بالقول، ويكون بالعمل، يكون بلسانه، ويكون بعمله، تقول العرب: حمل حملةً صادقةً، إذا جدَّ في قتال الكفَّار صارت الحملةُ الصَّادقة، فإذا عمل؛ صار صادقًا في قوله، فالذي يقول: الصلاة فريضة، ويُؤديها؛ هذا هو الصَّادق، وإذا قال: فريضة، ولم يُؤدها؛ صار قوله ضعيفًا، ليس بصادقٍ الصدق الكامل حتى يعمل، وإذا قال: الزكاة حقّ، ولم يعمل؛ صار قوله ناقصًا، وإيمانه ناقصًا، حتى يُؤديها. س: على هذا يكون الإيمانُ في اللغة: التَّصديق الجازم؟ ج: يكون التَّصديق بالقول، ويكون بالعمل أيضًا، ويكون تصديق بالعمل أيضًا من حيث اللغة، فالذي يحمل على الكفَّار حملةً قويةً يُقال له: صادق، والذي يحمل حملًا ضعيفًا ويتقهقر ليس بصادقٍ، والذي يقول: إني أُكرم الضيف، وأنَّ إكرام الضيف حقٌّ، ثم لا يُكرمه، ليس بصادقٍ، فإذا أكرم الضيفَ صار صادقًا، أي: صادقًا بالعمل، ولو قال: الضيف له حقّ -حق الكرامة- يجب إكرامه، ولكنه لا يُكرمه؛ ما كان صادقًا، بل كان قوله ضعيفًا، يكون مُكذِّبًا لعمله، وعمله مُكَذِّب لقوله. س: أليس التَّصديق يُقابل الكذب؟ ج: يكون بالقلب، ويكون باللسان، ويكون بالعمل، هذا التَّصديق في اللغة وفي الشَّرع. س: لكن في محض اللُّغة أليس التَّصديقُ يُقابل بالكذب، والإيمان يُقابل بالكفر؟ ج: نعم، والكذب يكون بالعمل أيضًا، فالذي يقول: إن إكرام الضيف حقٌّ، ثم لا يُكرمه، يُهينه؛ كاذب، عمله يُكذب قوله.[1]","link":"https://binbaz.org.sa/fatwas/31377/ما-حكم-القول-بان-الايمان-لغة-هو-التصديق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 006.mp3","categories":["الإسلام والإيمان"]},{"id":6124,"question":"هل يجوز قول المؤمن -أنا مؤمن إن شاء الله- نرجو توضيح ذلك؟","title":"حكم الاستثناء في الإيمان","answer":"الجواب: نعم، يجوز عند أهل السنة والجماعة أن يقول: أنا مؤمن -إن شاء الله- وليس المراد الشك، لكن المراد -إن شاء الله- لأنه لا يدري هل استكمل الإيمان، أم لا؟ الإيمان له واجبات، وله أشياء تتعلق بترك المحرمات، فيقول: إن شاء الله، أي: إن شاء الله كمال إيماني، وتمام إيماني، أو بالنسبة للعاقبة؛ لأنه لا يدري ما يختم له به، فيقول: إن شاء الله؛ لأنه ما يدري ما هي الخاتمة. والمرجئة تنكر ذلك، ويقولون للشك، وهذا غلط، وأهل السنة والجماعة يستثنون في الإيمان من دون شك، بل بالنظر إلى استكمال واجبات الإيمان، وبالنظر إلى الخاتمة.","link":"https://binbaz.org.sa/fatwas/1532/حكم-الاستثناء-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_462.mp3","categories":["الإسلام والإيمان","الإسلام والإيمان"]},{"id":6124,"question":"هل يجوز قول المؤمن -أنا مؤمن إن شاء الله- نرجو توضيح ذلك؟","title":"حكم الاستثناء في الإيمان","answer":"الجواب: نعم، يجوز عند أهل السنة والجماعة أن يقول: أنا مؤمن -إن شاء الله- وليس المراد الشك، لكن المراد -إن شاء الله- لأنه لا يدري هل استكمل الإيمان، أم لا؟ الإيمان له واجبات، وله أشياء تتعلق بترك المحرمات، فيقول: إن شاء الله، أي: إن شاء الله كمال إيماني، وتمام إيماني، أو بالنسبة للعاقبة؛ لأنه لا يدري ما يختم له به، فيقول: إن شاء الله؛ لأنه ما يدري ما هي الخاتمة. والمرجئة تنكر ذلك، ويقولون للشك، وهذا غلط، وأهل السنة والجماعة يستثنون في الإيمان من دون شك، بل بالنظر إلى استكمال واجبات الإيمان، وبالنظر إلى الخاتمة.","link":"https://binbaz.org.sa/fatwas/1532/حكم-الاستثناء-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_462.mp3","categories":["الإسلام والإيمان","الإسلام والإيمان"]},{"id":7299,"question":"هل أصل الإيمان عند جميع المؤمنين سواء، أم أنه يختلف من شخص إلى شخص، نرجو عرضه للأهمية؟","title":"حقيقة أصل الإيمان وتفاوت الناس فيه","answer":"الجواب: أصل الإيمان واحد، وهو الإيمان بالله، ورسله، وملائكته، وكتبه، واليوم الآخر، وبكل ما أخبر الله به ورسوله، لكن يتفاوت، ليس إيمان محمد ﷺ وأبي بكر وعمر وعثمان وبقية الصحابة مثل إيمان من بعدهم، يختلف في القوة والكمال والتمام والتأثير، ولكن أصله الإيمان بالله وبملائكته وكتبه ورسوله واليوم الآخر وبالقدر خيره وشره، والإيمان بكل ما شرعه الله ورسوله، والإيمان بكل ما أخبر الله به ورسوله من أمر الآخرة، والجنة والنار وغير ذلك.  لكن بالعلم والاجتهاد والتفقه في الدين، والغيرة لله، والخشية لله يزداد هذا الإيمان، ويقوى حتى يؤدي العبد الواجبات، وحتى ينتهي عن المحرمات، وبالجهل وبالإعراض ومجالسة الأشرار، واتباع الشهوات؛ يضعف هذا الإيمان، ولهذا قال العلماء: إن الإيمان يزيد وينقص، يزداد بالطاعات وينقص بالمعاصي، فالإيمان: قول باللسان وعمل بالجوارح، وعمل بالقلب وإيمان به.  فمن وفقه الله للعلم النافع، والبصيرة النافذة، والخوف من الله، والخشية له، ومجالسة الأخيار، والسير على سيرة الأخيار؛ قوي إيمانه، وعلا إيمانه، وكمل إيمانه، ومن كان بخلاف ذلك لجهله، أو اتباعه هواه، أو مجالسته الأشرار، أو غير؛ هذا من الأسباب التي تضعف الإيمان، قد يضعف كثيرًا حتى يزول بالكلية ويرتد عن دينه -نسأل الله العافية- وقد يضعف دون ذلك بأسباب المعاصي، ولهذا قال العلماء: إنه يزيد بالطاعة، وينقص بالمعاصي.","link":"https://binbaz.org.sa/fatwas/3366/حقيقة-اصل-الايمان-وتفاوت-الناس-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1685.mp3","categories":["الإسلام والإيمان"]},{"id":8024,"question":"في الحقيقة إن سؤال الأخت في الإسلام من العراق هذا السؤال فيه شيء يتردد بين أوساط الناس، يقولون مثلاً: الصلاة يشترط لها الإسلام، والحج أيضاً يشترط له الإسلام، فإن الإنسان قد يكون مسلماً ولو لم يأت ببقية أركان الإسلام، وأنتم أجبتم على هذا، لكن نريد أيضاً تجلية هذا الموضوع؟","title":"حكم من يترك ركناً من أركان الإسلام","answer":"الجواب: هذا واضح، هو مسلم بالشهادتين متى أقر بالشهادتين ووحد الله عز وجل، وصدق رسوله محمد ﷺ دخل في الإسلام، ثم ينظر فإن صلى تم إسلامه، وإن لم يصل صار مرتداً، وهكذا لو أنكر الصلاة بعد ذلك صار مرتداً، أو أنكر الصيام قال: ما هو بواجب الصيام صيام رمضان، صار مرتداً، أو قال: الزكاة ما هي بواجبة، زكاة الإسلام ما هي بواجبة صار مرتداً، أو قال: الحج مع الاستطاعة غير واجب صار مرتداً، أو استهزأ بالدين، أو سب الرسول صلى الله عليه وسلم صار مرتداً، فهمنا؟ هذا ينبغي أن يكون واضحاً، فهو إذا دخل في الإسلام بالشهادتين حكم له بالإسلام، ثم ينظر بعد ذلك في بقية الأمور، فإن استقام على الحق تم إسلامه، وإن وجد منه ما ينقض الإسلام من سب الدين، من تكذيب الرسول ﷺ، من جحد لما أوجب الله من صلاة أو صوم، من جحد لما حرم الله، كما لو قال: الزنا حلال، يرتد عن الإسلام بهذا، ولو صلى وصام، ولو قال: أشهد أن لا إله إلا الله وأن محمداً رسول الله، لو قال: إن الزنا حلال وهو يعلم الأدلة وقد أقيمت عليه الحجة يكون كافراً بالله كفراً أكبر نعوذ بالله، أو قال: الخمر حلال، وقد بين له الأدلة ووضحت له الأدلة، ثم أصر يقول: الخمر حلال، يكون كفراً أكبر، ردة عن الإسلام نعوذ بالله، أو قال مثلاً: إن العقوق كونه يعق والديه حلال يكون ردة عن الإسلام نعوذ بالله، أو قال: إن شهادة الزور حلال يكون ردة عن الإسلام بعد أن يبين له الأدلة الشرعية.\nكذلك إذا قال: الصلاة ما هي بواجبة، الزكاة ما هي بواجبة، صيام رمضان ما هو بواجب، الحج مع الاستطاعة ما هو بواجب كل هذه نواقض من نواقض الإسلام، يكون كافراً.\nإنما الخلاف إذا قال: الصلاة واجبة ولكن لا أصلي، هذا محل الخلاف، هل يكفر أو ما يكفر، هو يقول: الصلاة واجبة ولكن أنا أتساهل ما أصلي، فجمهور الفقهاء يقولون: لا يكفر، ويكون عاصياً يستتاب فإن تاب وإلا قتل حداً.\nوذهب آخرون من أهل العلم وهو المنقول عن الصحابة رضي الله عنهم أنه يكفر بها كفراً أكبر، فيستتاب فإن تاب وإلا قتل كافرا؛ لقول الله جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أن الذي لا يقيم الصلاة لا يخلى سبيله بل يستتاب فإن تاب وإلا قتل، وقال: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَإِخْوَانُكُمْ فِي الدِّينِ [التوبة:11] فدل على أن الذي لا يقيم الصلاة -لا يصلي- ليس بأخ في الدين. نعم.","link":"https://binbaz.org.sa/fatwas/5629/حكم-من-يترك-ركنا-من-اركان-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07804.mp3","categories":["الإسلام والإيمان"]},{"id":8028,"question":"أيضاً تسأل الأخت في الإسلام من بغداد في العراق، تقول: هل الإيمان بالقلب كفاية أن يكون الإنسان مسلماً بعيداً عن الصلاة والصوم والزكاة؟","title":"حكم الاكتفاء بإيمان القلب دون العمل","answer":"الجواب: لا يكفي الإيمان بالقلب لا يكفي عن الصلاة وغيرها، يجب أن يؤمن بقلبه وأن الله واحد لا شريك له وأنه ربه وخالقه، يجب أن يخصه بالعبادة سبحانه وتعالى، ويؤمن بالرسول محمد ﷺ وأنه رسول الله حقاً إلى جميع الناس كل هذا لا بد منه، هذا أصل الدين وأساسه.\nلكن لابد مع ذلك من الصلاة وبقية أمور الدين، فإذا صلى فقد أدى ما عليه، وإن لم يصل كفر؛ لأن ترك الصلاة كفر، أما الزكاة والصيام والحج وبقية الأمور إذا اعتقدها وأنها واجبة ولكن تساهل ما يكفر بذلك يكون عاصي، يكون إيمانه ضعيفاً ناقصاً؛ لأن الإيمان يزيد وينقص، يزيد الإيمان بالطاعات والأعمال الصالحات وينقص بالمعاصي، أما الصلاة وحدها خاصة فإن تركها كفر عند جمع من أهل العلم وهو أصح قولي العلماء بخلاف بقية أمور العبادات من الزكاة والصوم والحج ونحو ذلك فإن تركها ليس بكفر على الصحيح -يعني: كفر أكبر- ولكن نقص في الإيمان وضعف في الإيمان، وكبيرة عظيمة ترك الزكاة كبيرة عظيمة، ترك الصيام كبيرة عظيمة، ترك الحج مع الاستطاعة كبيرة عظيمة، ولكن لا يكون كفراً أكبر إذا كان مؤمناً بأن الزكاة حق، وأن الصيام حق، وأن الحج مع الاستطاعة حق، ما كذب بذلك ولا أنكر وجوب ذلك، ولكنه تساهل بالفعل فلا يكون كافراً بذلك على الصحيح.\nأما الصلاة فإنه إذا تركها يكفر في أصح قولي العلماء كفراً أكبر نعوذ بالله إن تركها بالكلية، وأما الشهادتان بأن الله رب الجميع وإله الجميع وأنه لا إله سواه، يعني: لا معبود بحق سواه، والشهادة بأن محمداً رسول الله هاتان الشهادتان هما أصل الدين هما أساس الملة، فذهب جمع من أهل العلم وهو قول الأكثر من الفقهاء أنه يكون مسلماً بذلك، ولو لم يصل إذا كان يعتقد وجوب الصلاة، والصوم، والحج إلى غير ذلك، لكن لا يفعل يتساهل فإن الأكثر من الفقهاء لا يكون كافراً كفراً أكبر إذا ترك ذلك، يبقى مسلماً عاصياً على خطر من دخول النار، ولا يكفر بذلك.\nوذهب جمع من أهل العلم إلى أن ترك الصلاة كفر أكبر وهو الأرجح كما تقدم وهو الأصح؛ لقول النبي ﷺ العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر؛ ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة كما تقدم في جواب سؤال سابق.\nفينبغي الانتباه لهذا، أما بقية أمور الدين الواجبة من الزكاة والصوم والحج ونحو ذلك، إذا كان المؤمن بالله ورسوله يعتقد وجوبها ولا ينكر وجوبها، ولكنه قد يتساهل في فعلها فهذا لا يكون كفراً أكبر ولكن يكون نقصاً في الإيمان ويكون ضعفاً في الإيمان، ويكون عاصياً مستحقاً لدخول النار وغضب الله إلا أن يعفو الله عنه سبحانه وتعالى؛ لقوله عز وجل: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] فجعل ما دون الشرك تحت مشيئة الله، فعلم بذلك أن المعاصي تحت مشيئة الله ولا يكون بها كافراً كفراً أكبر، بل يكون عاصياً، ويكون ضعيف الإيمان. نعم.","link":"https://binbaz.org.sa/fatwas/5627/حكم-الاكتفاء-بايمان-القلب-دون-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07803.mp3","categories":["مسائل متفرقة في العقيدة","الإسلام والإيمان"]},{"id":8183,"question":"أخونا يسأل سؤال في نهاية رسالته ويقول: كم هي شروط الإسلام؟","title":"شروط الإسلام","answer":"الجواب: شروط الإسلام شرطان:\nالشرط الأول: الإخلاص لله وأن تكون قصدت بإسلامك ودخولك في دين الله وأعمالك وجه الله عز وجل هذا لابد منه، كل عمل تعمله وليس لوجه الله سواء أن كان صلاة أو صدقة أو صيام أو غير هذا ما يكون نافعاً ولا مقبولاً حتى الشهادتين لو فعلتهما رياءً أو نفاقاً ما تقبل ما تنفع تكون من المنافقين فلابد أن يكون قولك أشهد أن لا إله الله وأشهد أن محمداً رسول الله صدقاً من قلبك، تؤمن بالله وحده وأنه المعبود بالحق وأن محمداً رسول الله صادق وأنه رسول الله حقاً وأنه خاتم الأنبياء فإذا كان صدقاً إخلاصاً نفعك ذلك وهكذا في صلاتك تعبد الله بها وحده هكذا صدقاتك هكذا قراءتك تهليلك صومك حجك يكون لله وحده.\nالشرط الثاني: الموافقة للشريعة لابد تكون أعمالك موافقة للشريعة ما هو من عندك رأيك ولا من اجتهادك لابد تتحرى موافقة الشريعة تصلي كما شرع الله، تصوم كما شرع الله، تزكي كما شرع الله، تجاهد كما شرع الله، تحج كما شرع الله هكذا يقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد والله يقول في كتابه العظيم: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] يعيبهم بهذا، ويقول سبحانه: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا وَلا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لا يَعْلَمُونَ إِنَّهُمْ لَنْ يُغْنُواا عَنكَ مِنَ اللَّهِ شَيْئًا [الجاثية:18].\nفالواجب اتباع الشريعة التي شرعها الله على يد رسوله محمد صلى الله عليه وسلم وعدم الخروج عنها في جميع العبادات التي يتقرب بها إلى الله سبحانه وتعالى، هذه شروط الإسلام شرطان:\nالأول: الإخلاص لله في العمل.\nوالثاني: الموافقة للشريعة هذا هو الذي به تنتفع بعباداتك ويقبل الله منك عباداتك إذا كنت مسلماً.\nنعم.","link":"https://binbaz.org.sa/fatwas/5990/شروط-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10511.mp3","categories":["الإسلام والإيمان"]},{"id":8689,"question":"شيخ عبد العزيز! اقترح بعض المستمعين أن يطرح البرنامج أسئلة عن الركن الأول من أركان الإسلام، وها هو البرنامج يستجيب لذلكم الاقتراح، اشرحوا لنا لو تكرمتم معنى الركن الأول من أركان الإسلام، وما يقتضيه ذلك المعنى، وكيف يتحقق في الإنسان، وما حكم من جهل شيئاً منه؟","title":"معنى الركن الأول من أركان الإسلام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله بعث نبيه محمداً ﷺ إلى الناس عامة، عربهم وعجمهم.. جنهم وإنسهم.. ذكورهم وإناثهم، يدعوهم إلى توحيد الله والإخلاص له، وإلى الإيمان به عليه الصلاة والسلام وبما جاء به، وإلى الإيمان بجميع المرسلين، وبجميع الملائكة، والكتب المنزلة من السماء، وباليوم الآخر وهو: البعث والنشور والجزاء والحساب والجنة والنار، وبالقدر خيره وشره وأن الله قدر الأشياء وعلمها وأحصاها وكتبها سبحانه وتعالى، فكل شيء يقع هو بقضاء الله وقدره سبحانه وتعالى، وأمر الناس أن يقولوا: (لا إله إلا الله) هذا هو أول شيء دعا إليه، وهو الركن الأول من أركان الإسلام: شهادة: أن لا إله إلا الله وأن محمداً رسول الله، فلما قال للناس: قولوا: لا إله إلا الله، وأمرهم أن يؤمنوا بأنه رسول الله عليه الصلاة والسلام امتنع الأكثرون وأنكروا هذه الدعوة، وقالت له قريش ما ذكر الله عنهم: أَجَعَلَ الآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ [ص:5].\nوقال سبحانه عنهم: إِنَّهُمْ كَانُوا إِذَا قِيلَ لَهُمْ لا إِلَهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ ۝ وَيَقُولُونَ أَئِنَّا لَتَارِكُوا آلِهَتِنَا لِشَاعِرٍ مَجْنُونٍ [الصافات:35-36]، فاستنكروا هذه الدعوة؛ لأنهم عاشوا على عبادة الأوثان والأصنام واتخاذ الآلهة مع الله عز وجل، فلهذا أنكروا دعوة الرسول عليه الصلاة والسلام إلى توحيد الله والإخلاص له.\nوهذا الذي دعا إليه ﷺ هو الذي دعت إليه الرسل جميعاً، كما قال سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُواا الطَّاغُوتَ [النحل:36]، وقال سبحانه: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25].\nوفي الصحيحين عن ابن عمر رضي الله تعالى عنهما عن النبي ﷺ أنه قال: بني الإسلام على خمس: -يعني: على خمس دعائم-- شهادة أن لا إله إلا الله، وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، وفي الصحيح أيضاً عن عمر بن الخطاب  أن النبي ﷺ: أتاه سائل يسأله في صورة رجل شديد بياض الثياب شديد سواد الشعر لا يرى عليه أثر السفر ولا يعرفه من الحاضرين أحد، فقال: يا محمد أخبرني عن الإسلام؟ فقال: الإسلام: أن تشهد أن لا إله إلا الله، وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً، قال: صدقت، قال الصحابة: فعجبنا له يسأله ويصدقه، ثم قال: أخبرني عن الإيمان؟ قال: الإيمان أن تؤمن بالله وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشره، قال: صدقت، قال: فأخبرني عن الإحسان؟ قال: أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك .. الحديث ، ثم أخبرهم النبي ﷺ أن هذا هو جبرائيل أتاهم يعلمهم دينهم، لما لم يسألوا أتاهم جبرائيل بأمر الله يسأل الرسول عن هذا الدين العظيم حتى يتعلموا ويستفيدوا.\nفدين الإسلام مبني على هذه الأركان الخمسة الظاهرة:\nأولها: شهادة: أن لا إله إلا الله وأن محمداً رسول الله.\nثانيها: إقام الصلوات الخمس.\nثالثها: أداء الزكاة.\nرابعها: صوم رمضان.\nخامسها: حج بيت الله الحرام.\nوعلى أركان باطنة إيمانية في القلب وهي: الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وبالقدر خيره وشره، فلابد من هذه الأصول، لابد أن يؤمن المؤمن المكلف بهذه الأصول الستة الباطنية التي تتعلق بالقلب، فيؤمن أن الله ربه وإلهه ومعبوده الحق سبحانه وتعالى، ويؤمن بملائكة الله، وبكتب الله التي أنزلها على الأنبياء من التوراة والإنجيل والزبور والقرآن وغير ذلك، ويؤمن أيضاً بالرسل الذين أرسلهم الله إلى عباده أولهم نوح وآخرهم محمد عليه الصلاة والسلام، وهم كثيرون، بين الله بعضهم في القرآن العظيم، ونؤمن أيضاً باليوم الآخر، وهو البعث بعد الموت، والجزاء من عند الله عز وجل، أهل الإيمان لهم السعادة وأهل الكفر لهم الخيبة والندامة والنار.\nولابد من الإيمان بالقدر خيره وشره وأن الله قدر الأشياء وعلمها وكتبها وأحصاها فما شاء الله كان وما لم يشأ لم يكن، وكل ما يقع في الوجود من خير وشر وطاعة ومعصية فقد سبق بهذا علم الله وكتابته وقدره سبحانه وتعالى.\nفالأصل العظيم الأول الذي طالبت به الرسل هو: الإيمان بأن الله هو الإله الحق سبحانه وتعالى، وهو معنى شهادة: أن لا إله إلا الله، فهذا أصل أصيل أجمعت عليه الرسل عليهم الصلاة والسلام، كلهم دعوا إلى هذا الأصل الأصيل، وهو أن يؤمن الناس بأن الله هو الإله الحق، وأنه لا معبود بحق سواه، وهذا هو معنى: لا إله إلا الله، أي: لا معبود حق إلا الله وما عبده الناس من أصنام أو أشجار أو أحجار أو أنبياء أو أولياء أو ملائكة كله باطل، العبادة بحق لله وحده سبحانه وتعالى: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ[البقرة:163] .. وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُواا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].\nولابد مع هذا الأصل من الإيمان بالرسول عليه الصلاة والسلام، في عهد نوح الإيمان بـنوح ، وفي عهد هود الإيمان بـهود مع توحيد الله، وفي عهد صالح الإيمان بـصالح مع توحيد الله، وهكذا في عهد كل رسول، لابد من توحيد الله والإيمان بأنه لا إله إلا الله ولابد من الإيمان بالرسول الذي بلغ الرسالة في عهده إلى آخرهم عيسى عليه الصلاة والسلام آخر أنبياء بني إسرائيل عيسى بن مريم عليه الصلاة والسلام.\nثم بعث الله خاتمهم وأفضلهم نبينا محمد ﷺ، فـعيسى هو آخر أنبياء بني إسرائيل ومحمد هو آخر الأنبياء وخاتم الأنبياء جميعاً ليس بعده نبي ولا رسول عليه الصلاة والسلام، وهو أفضل الرسل وهو إمامهم وهو خاتمهم.\nفلابد في حق الأمة أمة محمد ﷺ جنها وإنسها.. عربها وعجمها.. ذكورها وإناثها.. أغنيائها وفقرائها.. حكامها ومحكوميها لابد أن يؤمنوا بهذا النبي، فمن لم يؤمن به فلا إسلام له ولا دين له، فلابد من الإيمان بأن الله هو الإله الحق وأنه لا إله حق إلا الله، ولابد من الإيمان بمحمد ﷺ وأنه رسول الله حقاً إلى جميع الناس، فمن لم يؤمن بهاتين الشهادتين فليس بمسلم.\nلابد من الإيمان بهما واعتقاد معناهما، وأن معنى: (لا إله إلا الله) معناها: لا معبود حق إلا الله، فلا يجوز أن يدعى مع الله ملك أو نبي أو شجر أو حجر أو جن أو صنم لا. فإذا قال: يا رسول الله! انصرني بعد موته صلى الله عليه وسلم، أو قال: يا بدوي ، يا سيدي البدوي ! انصرني، أو اشف مريضي، أو يا سيدي الحسين ! أو يا سيدي عبد القادر ! أو المدد المدد صار هذا شركاً بالله عز وجل، يبطل معنى: لا إله إلا الله، يعني: يبطل قولك: لا إله إلا الله؛ لأنك لم تأت بالعبادة لله وحده بل شركت مع الله غيره، ودعوت مع الله غيره، والله يقول: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكََ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، ويقول جل وعلا: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، ويقول النبي ﷺ: الدعاء هو العبادة، ويقول جل وعلا: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، فلابد من إخلاص العبادة لله وحده ومنها الدعاء، فإذا قلت للميت أو للشجر أو للصنم: أغثني، انصرني، اشف مريضي، المدد المدد صار شركاً بالله، وصار نقضاً لقول: لا إله إلا الله.\nوهكذا من كذب الرسول محمد صلى الله عليه وسلم، أو شك في رسالته، أو قال: إنه للعرب دون العجم، أو قال: إنه ليس خاتم النبيين بل بعده نبي، كل هذا كفر وضلال ونقض للإسلام نسأل الله العافية، فلابد من الإيمان بأنه رسول الله حقاً إلى جميع الثقلين الجن والإنس، ولابد من الإيمان بأنه خاتم الأنبياء والمرسلين ليس بعده نبي، وأن من ادعى النبوة بعده كـمسيلمة الكذاب كافر بالله كذاب، كـمسيلمة والأسود العنسي في اليمن، وسجاح التميمية وطليحة الأسدي وجماعة ادعوا النبوة بعده، فأجمع الصحابة رضي الله عنهم وأرضاهم على كفرهم وقاتلوهم؛ لأنهم كذبوا معنى قوله سبحانه: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40]، قد تواترت الأحاديث عن رسول الله ﷺ أنه قال: أنا خاتم النبيين لا نبي بعدي عليه الصلاة والسلام.\nفهذه الشهادة التي هي: شهادة أن لا إله إلا الله وأن محمداً رسول الله هي الأصل الأصيل، وهي الركن الأول من أركان الإسلام، فلا إسلام إلا بهاتين الشهادتين، لو صلى وصام وحج وصام النهار وقام الليل وذكر الله كثيرا ولكنه لا يؤمن بأن الله هو المستحق للعبادة، لا يؤمن بمعنى: لا إله إلا الله، بل يرى أنه لا مانع من عبادة الأوثان والأصنام، لا يرى مانعاً من عبادة البدوي أو الحسين أو الشيخ عبد القادر أو علي بن أبي طالب أو غيرهم، إذا اعتقد أنه يجوز هذا، يدعون من دون الله، يستغاث بهم.. ينذر لهم صار شركاً بالله عز وجل، وصار كلامه هذا وعقيدته هذه ناقضة لقول: لا إله إلا الله.\nوهكذا لو قال: إن محمداً ﷺ ليس بخاتم الأنبياء، أو ليس مرسلاً للثقلين بل هو للعرب خاصة، كان كافراً بالله عز وجل، فلابد أن يؤمن بأنه رسول الله إلى جميع الثقلين، ولابد أن يؤمن بأنه خاتم الأنبياء ليس بعده نبي ولا رسول، هذا هو الأصل الأصيل.\nثم بعد هذا يطالب المسلم بعد بالصلاة، يطالب بالزكاة، بالصيام، بالحج، ببقية الأوامر وترك النواهي بعدما يثبت هذا الأصل، بعد إيمانه بشهادة: أن لا إله إلا الله وأن محمداً رسول الله، يعني: إيمانه بأن الله سبحانه هو المعبود بالحق وأن العبادة حقه وحده وأنه لا يعبد معه سواه لا نبي ولا ملك ولا شجر ولا صنم ولا غير ذلك، ولابد من الإيمان بأن محمداً رسول الله مع التصديق بجميع الأنبياء الماضيين، وأنهم أدوا الرسالة وبلغوها عليهم الصلاة والسلام مع الإيمان بجميع ما تقدم من الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر وبالقدر خيره وشره، لابد من هذا وهذا، ولابد أيضاً مع هذا كله من التصديق بما أخبر الله به ورسوله عما كان وما يكون، فالله صادق في خبره ورسوله صادق عليه الصلاة والسلام، فمن كذب الله أو كذب الرسول صلى الله عليه وسلم كفر ولو صلى وصام، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/6836/معنى-الركن-الاول-من-اركان-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_130/13001.mp3","categories":["الإسلام والإيمان"]},{"id":8691,"question":"ارتكاب بعض المعاصي -سماحة الشيخ- ولاسيما الكبائر، هل تؤثر على هذا الركن من أركان الإسلام؟","title":"حكم مرتكب الكبيرة في الإسلام","answer":"الجواب: نعم، ارتكاب الكبائر كالزنا وشرب الخمر وقتل النفس بغير حق وأكل الربا والغيبة والنميمة وما أشبه هذا من المعاصي والكبائر تؤثر في توحيد الله وفي الإيمان بالله وتضعفه، يعني: يكون ضعيف الإيمان لكن ما يكفر كما تقول الخوارج لا. الخوارج تكفره.. تجعله كافراً إذا زنى أو سرق أو عق والديه أو أكل الربا تجعله كافراً وإن لم يستحل ذلك، وهذا غلط من الخوارج ، أهل السنة والجماعة يقولون: لا. هو عاصي وهو ضعيف الإيمان وناقص الإيمان وناقص التوحيد، وهذا يضعف شهادته ويضعف إيمانه لكن لا يكفر كفراً أكبر، بل يكون فيه نقص، فيه ضعف، ولهذا شرع الله في الزاني حداً إذا كان بكر يجلد مائة ويغرب عاماً، ولو كان الزنا ردة كان قتل، فدل على أنه ليس بردة، والسارق ما يقتل يقطع تقطع يده، فدل ذلك على أن هذه المعاصي ليست ردة، ولكنها ضعف في الإيمان ونقص في الإيمان فلهذا شرع الله تأديبهم وتعزيرهم بهذه الحدود ليتوبوا ويرجعوا إلى ربهم، ويرتدعوا عما حرم الله عليهم ربهم سبحانه وتعالى.\nوقالت المعتزلة: إنه في منزلة بين المنزلتين ولكن يخلد في النار إذا مات عليها، فخالفوا أهل السنة في تخليد العاصي في النار، ووافقوا الخوارج في ذلك، والخوارج قالوا: يكفر ويخلد في النار جميعاً، وطائفة يقال لها: المعتزلة هؤلاء قالوا: يخلد في النار ولكن لا نسميه كافراً، يعني: كفر أكبر، وكلاهما، وكلتا الطائفتين قد ضلتا عن السبيل.\nوالصواب قول أهل السنة والجماعة: أنه لا يكون كافراً يعني: كفر أكبر، ولكن يكون عاصياً، ويكون ضعيف الإيمان، ناقص الإيمان، على خطر عظيم من الكفر ولكن ليس بكافر إذا كان ما استحل ذلك، إذا لم يستحل هذه المعصية بل فعلها وهو يعلم أنها معصية يدري أنها معصية ولكن حمله عليها الشيطان والهوى والنفس الأمارة بالسوء، فهذا هو قول أهل الحق.\nفيكون إيمانه ضعيفاً ويكون توحيده ضعيفاً ولكن لا يكون كافراً الكفر الأكبر الذي هو الردة عن الإسلام نعوذ بالله من ذلك، ولا يخلد في النار أيضاً لو مات عليها، إذا مات الزاني على الزنا ما تاب أو على السرقة ما تاب أو على الربا ما تاب وهو يعلم أنه محرم فهذا يكون تحت مشيئة الله، إن شاء الله غفر له وإن شاء عذبه على قدر معاصيه سبحانه وتعالى، العذاب الذي تقتضيه حكمته سبحانه وتعالى، ثم بعد مضي ما حكم الله عليه به يخرجه الله من النار إلى الجنة.\nفهذا قول أهل الحق، وهذا الذي تواترت به الأخبار عن رسول الله ﷺ خلافاً للخوارج والمعتزلة ، والله يقول سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فعلق ما دون الشرك بمشيئته سبحانه وتعالى.\nأما من مات على الشرك فإنه لا يغفر له أبداً والجنة عليه حرام نعوذ بالله من ذلك، وهو مخلد في النار أبد الآباد، أما العاصي فإن دخل النار فإنه لا يخلد أبد الآباد بل يبقى فيها ما شاء الله، وقد تطول مدته ويكون هذا خلوداً لكنه خلود مؤقت ليس مثل خلود الكفار، كما قال في آية الفرقان لما ذكر المشرك والقاتل والزاني قال: وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:69]، فهو خلود مؤقت له نهاية، يعني: طويل نسأل الله...، أما المشرك فلا، المشرك خلوده دائم نعوذ بالله أبد الآباد، ولهذا قال سبحانه في المشركين: كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ [البقرة:167]، هكذا في سورة البقرة، وقال في سورة المائدة في حق الكفرة: يُرِيدُونَ أَنْ يَخْرُجُوا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُقِيمٌ [المائدة:37]، نسأل الله العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6838/حكم-مرتكب-الكبيرة-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_130/13003.mp3","categories":["الإسلام والإيمان"]},{"id":8692,"question":"يسأل البرنامج أيضاً سماحة الشيخ: هل يكفي النطق والاعتقاد بهذا الركن من أركان الإسلام، أم لابد من أشياء أخر حتى يكتمل إسلام المرء ويكتمل إيمانه؟","title":"حكم الاكتفاء بالنطق والاعتقاد في الشهادتين","answer":"الجواب: هذا الركن يدخل به في الإسلام، إذا شهد أن لا إله إلا الله وأن محمداً رسول الله عن صدق وعن يقين وعن علم بمعناها وعمل بذلك يدخل في الإسلام، ثم يطالب بالصلاة وما سواها من الأحكام، ولهذا لما بعث النبي ﷺ معاذ إلى اليمن قال له: ادعهمم إلى أن يشهدوا: أن لا إله إلا الله وأن محمداً رسول الله، فإذا فعلوا ذلك فأعلمهم أن الله افترض عليهم خمس صلوات في اليوم والليلة،، فإن هم أطاعوك لذلك فأعلمهم أن الله افترض عليهم صدقة تؤخذ من أغنيائهم فترد في فقرائهم، فلم يأمرهم بالصلاة إلا بعد التوحيد والإيمان بالرسول صلى الله عليه وسلم، فهم يطالبون أولاً: بالتوحيد، والإيمان بالرسول ﷺ، فإذا دخل الكافر في ذلك وأسلم صار له حكم المسلمين، ثم يطالب بالصلاة وبقية أمور الدين، فإذا امتنع من ذلك صار له أحكام أخرى، إذا امتنع من الصلاة يستتاب فإن تاب وإلا قتل، وإذا امتنع من الزكاة وكابر عليها وقاتل دونها كذلك يقاتل كما قاتل الصحابة مانعي الزكاة، والصيام كذلك إذا امتنع يعزره الإمام ويؤدبه الإمام بما يردعه عن ترك الصيام، وهكذا الحج مع الاستطاعة إذا ترك وهو يستطيع يؤدب حتى يحج، وهكذا بقية المعاصي، الذي فيه حد يقام عليه الحد والذي ما فيه حد التعزير والتأديب.\nفالحاصل: أن الأصل هو الشهادتان، متى شهد: أن لا إله إلا الله وأن محمداً رسول الله دخل في الإسلام وصار له حكم المسلمين، فلو مات في الحال صار من أهل الجنة، فإن عاش إلى أن جاء وقت الصلاة مثل: أسلم بطلوع الشمس، ثم مات قبل الظهر هذا مات على الإسلام، وهو ما صلى شيء ولا فعل شيء، كما قد وقع لبعض الصحابة أسلموا وقتلوا في الحال فصاروا من أهل الجنة من دون أن يعملوا عملاً سوى التوحيد والشهادة للرسول بالرسالة عليه الصلاة والسلام والإيمان بالله ورسوله، فإن أدرك الصلاة يؤمر بالصلاة، ثم إذا جمع مالاً وحصل له عنده مال، حصل له مال توفي فيه الزكاة يؤمر بالزكاة، وإذا أدرك رمضان يؤمر بالصيام، وإذا استطاع الحج يؤمر بالحج في وقته، وهكذا. نعم.\nالمقدم: بارك الله فيكم، إذاً أصبح له حكم المسلمين من حيث؟\nالشيخ: جميع الأحكام.\nالمقدم: من جميع الأحكام.\nالشيخ: في الدنيا والآخرة، فيطالب بأمور الإسلام وحق الإسلام، ولو مات على حاله قبل أن تأتي الصلاة قبل أن يأتي وقت الصلاة مات على الإسلام الكامل ودخل الجنة، لكن لو عاش وأبى أن يصلي حينئذ هذا محل النظر، يطالب بالصلاة فإن أصر عليها كفر عند جمع من أهل العلم، إذا أصر على الترك ولم يستجب يكفر، وقال آخرون من أهل العلم: يكون كفراً دون كفر فيستحق القتل ولكن لا يكون كفراً أكبر كما لو ترك الزكاة أو الصيام، ولكن القول الصحيح: أنه متى ترك الصلاة بخصوصها لأن لها منزلة عظيمة الصلاة، إذا تركها عمداً تهاوناً وتكاسلاً صار حكمه حكم من جحدها يقتل كافراً على الصحيح.\nوأما جمهور الفقهاء فقالوا: يقتل عاصياً وحداً وكفراً دون كفر، هذا قول أكثر الفقهاء المتأخرين، يعني: بعد الصحابة، أما الصحابة فقد نقل عبد الله شقيق العقيلي إجماعهم على أن من تركها كفر، نعم، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6839/حكم-الاكتفاء-بالنطق-والاعتقاد-في-الشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_130/13004.mp3","categories":["الإسلام والإيمان"]},{"id":8793,"question":"السؤال الثالث في رسالة الأخ صالح عبده اليماني من مدينة الخبر، يقول: ما معنى شهادة أن لا إله إلا الله، وما معنى شهادة أن محمداً رسول الله، أفيدونا أثابكم الله؟","title":"معنى الشهادتين","answer":"الجواب: هاتان الشهادتان هما أصل الإسلام، وهما أساس الملة، وبهما يدخل الكافر الذي لا ينطق بهما، بهما يدخل في الإسلام، ويحسب من أهل الإسلام، ويطالب ببقية حقوق الإسلام.\nأما شهادة أن لا إله إلا الله، فهي: أصل الملة، وأساس الدين في جميع الأديان، جميع أديان الرسل، من آدم إلى يومنا هذا، جاء بها آدم عليه الصلاة والسلام، وجاءت بها الرسل كـنوح وهود وصالح وإبراهيم وغيرهم من الرسل، كلهم دعوا الأمم إلى هذه الكلمة، قال تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36]، قال تعالى: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25] ونبينا ﷺ محمد لما بعثه الله بدأ قومه بهذا، فقال لهم: قولوا: لا إله إلا الله تفلحوا ولما كانوا يعبدون الأصنام والأشجار، وكانت لهم آلهة كثيرة حول الكعبة وفي غيرها استنكروا هذا، وقالوا: أَجَعَلَ الآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ [ص:5] فاستنكروا التوحيد والإيمان لجهلهم وكفرهم، وضلالهم واعتيادهم ما كان عليه آباؤهم من الشرك والكفر وعبادة الآلهة الكثيرة.\nوهذه الكلمة هي أفضل شعب الإيمان، كما في الصحيح عن النبي ﷺ أنه قال: الإيمان بضع وستون شعبة -أو قال:- بضع وسبعون شعبة، فأفضلها قول: لا إله إلا الله وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان فهذا الحديث العظيم يدلنا على أن أصل الدين وأساس الملة وأفضل الكلام هو قول: لا إله إلا الله، ومعناها: لا معبود حق إلا الله، فهي تنفي الإلهية وهي العبادة عن غير الله، وتثبتها لله وحده .\nوفي ... الصحيح من حديث صحيح مسلم .. عن ابن عمر رضي الله تعالى عنهما، عن النبي ﷺ أنه قال: بني الإسلام على خمس: على أن يوحد الله، وعلى إقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت وفي لفظ: على أن يعبد الله وحده ويكفر بما دونه فجعل توحيد الله، وعبادته وحده والكفر بما دونه جعل ذلك هو معنى: لا إله إلا الله، وفي الصحيحين من حديث أبي هريرة ، في سؤال جبرائيل ، أنه لما سأل الرسول عن الإسلام، قال عليه الصلاة والسلام: الإسلام: أن تعبد الله ولا تشرك به شيئاً، وتقيم الصلاة .. إلى آخره فجعل عبادة الله وحده وعدم الإشراك به هو معنى لا إله إلا الله، هذا هو معناها، معناها: إثبات العبادة لله وحده، وتخصيصه بها سبحانه وتعالى دون كل ما سواه، واعتقاد بطلانها عن غيره سبحانه، قال تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62] هذا هو معنى لا إله إلا الله، إثبات العبادة لله وحده، وهي: الإلوهية، ونفيها عما سواه، فلا يدعى إلا الله وحده، ولا يستغاث إلا به، ولا يتوكل إلا عليه، ولا يصلى إلا له، ولا ينذر إلا له، ولا يذبح إلا له، هكذا.\nوبهذا تعلم -أيها السائل وأيها المستمع الكريم- تعلم أن ما يفعله بعض الجهال عند بعض القبور ومع بعض الأولياء من استغاثة بالأموات، ودعاء الأموات، ودعاء الأشجار والأحجار، أو دعاء الأصنام والاستغاثة بهم، أن هذا هو الشرك الأكبر، وأن هذا يناقض قول: لا إله إلا الله.\nوأما شهادة أن محمداً رسول الله، فمعناها: الإيمان بأنه رسول الله حقاً، وأن الله أرسله إلى الثقلين الجن والإنس بشيراً ونذيرا عليه الصلاة والسلام، وأنه خاتم الأنبياء ليس بعده نبي كما قال الله جل وعلا: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40] وقد قال تعالى: يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا ۝ وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِ وَسِرَاجًا مُنِيرًا [الأحزاب:45-46] فهو رسول الله حقاً عليه الصلاة والسلام، بعثه الله إلى الناس كافة -جنهم وإنسهم- يدعوهم إلى توحيد الله، وينذرهم الشرك بالله، كما قال : قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا [الأعراف:158] قال تعالى: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا [سبأ:28].\nفيجب على كل مسلم وعلى كل مسلمة، بل على كل أحد؛ أن يؤمن بأن محمداً رسول الله، يجب على كل المكلفين، من المسلمين واليهود والنصارى وغيرهم، جميع المكلفين يجب عليهم أن يشهدوا أنه لا إله إلا الله، وأن يوحدوا الله ويخصوه بالعبادة، ويدعوا عبادة ما سواه من أصنام وأشجار وأحجار وأنبياء وأولياء وغير ذلك، ويجب عليهم أن يؤمنوا بأن محمداً رسول الله، ويصدقوا بأنه رسول الله حقاً، وأنه خاتم الأنبياء، وأن الواجب اتباعه؛ وذلك بتصديق ما جاء به، والإيمان بأنه رسول الله حقاً، وطاعة أوامره، وترك نواهيه، وألا يعبد الله إلا بشريعته عليه الصلاة والسلام، هذا هو معنى هذه الشهادة، شهادة أن محمداً رسول الله، تصديقه بما أخبر، وطاعته فيما أمر، واجتناب ما نهى عنه وزجر عليه الصلاة والسلام، وألا يعبد الله إلا بشريعته التي جاء بها عليه الصلاة والسلام، لا بالهوى ولا بالآراء ولا بالبدع، هذا هو معنى شهادة أن محمداً رسول الله.\nوهاتان الشهادتان -كما تقدم- هما أصل الدين وهما أساس الملة، ومن نطق بهما واعتقد معناهما فهو مسلم، وعليه أن يؤدي بقية الحقوق، من صلاة، وزكاة، وصوم، وحج، وغير هذا مما أمر الله به ورسوله، وعليه مع ذلك يجتنب ما حرم الله ورسوله من الزنا، والسرقة، والعقوق، وسائر المحرمات، كما أن عليه أن يجتنب الشرك الأكبر الذي هو ضد التوحيد، فعليه أن يجتنب الشرك الأكبر، ولا يتم له التوحيد إلا بذلك، وعليه أن يتجنب كل ما نهى الله عنه ورسوله من الأقوال والأعمال تحقيقاً لهاتين الشهادتين، والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6940/معنى-الشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22003.mp3","categories":["الإسلام والإيمان"]},{"id":11432,"question":"ما هو حكم الشرع في مرتكب الكبيرة، هل يخرج من الملة؟","title":"حكم مرتكب الكبيرة عند أهل السنة وغيرهم","answer":"الجواب:  حكم الشرع فيه أنه عاصي فاسق، لكن لا يخرج من الملة؛ خلافًا للخوارج، عند أهل السنة والجماعة الزاني فاسق، وشارب الخمر فاسق، إذا لم يستحل ذلك، العاق لوالديه فاسق، المرابي فاسق؛ لأن هذه كلها كبائر، لكن لا يكفر، وعند الخوارج يكفر بذلك نسأل الله العافية. والصحيح أن قولهم باطل، وأنه ليس بكافر، ولكنه، عاصي عليه التوبة إلى الله، والرجوع إلى الله، والإنابة، ومن تاب؛ تاب الله عليه، وإذا مات على ذلك؛ مات عاصيًا على خطر من دخول النار إلا أن يعفو الله عنه، لكن لو دخلها لا يخلد فيها، لو دخلها، خلافًا للخوارج والمعتزلة، الخوارج يقولون: يكفر، ويخلد في النار، إذا مات عاقًا لوالديه، أو على الزنا، لم يتب، أو على شرب الخمر يقولون: هو كافر، ومخلد في النار، والمعتزلة مثلهم في أمر الآخرة، يقولون: مخلد في النار، لكن يقولون في الدنيا: لا كافر ولا مسلم، في منزلة بين المنزلتين، وقولهم باطل أيضًا. أما أهل السنة والجماعة فيقولون: هو مسلم عاصي، مؤمن عاصي عليه التوبة إلى الله، فإن تاب؛ تاب الله عليه، وإن مات على معصيته؛ فهو تحت مشيئة الله، إن شاء الله عفا عنه، وأدخله الجنة بتوحيده وإسلامه، وإن شاء عذبه على قدر المعاصي التي مات عليها، ثم يخرج من النار بعد التطهير، يخرجه الله من النار إلى الجنة؛ لقول الله سبحانه في كتابه العظيم: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] ما دون الشرك لِمَنْ يَشَاءُ [النساء:48]، بعضهم لا يغفر له، يدخل النار، ويعذب على قدر المعاصي، وبعد التطهير والتمحيص يخرجهم الله من النار، إلى نهر يقال له: نهر الحياة، فينبتون فيه كما تنبت الحبة في حميل السيل، فإذا تم خلقهم؛ أدخلهم الله الجنة، نعم.","link":"https://binbaz.org.sa/fatwas/9614/حكم-مرتكب-الكبيرة-عند-اهل-السنة-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29408.mp3","categories":["الإسلام والإيمان"]},{"id":12426,"question":"أختنا من الإحساء (م. خ) تسأل وتقول: في حديث للرسول ﷺ: يولد المولود على الفطرة، فأبواه يهودانه، أو ينصرانه، أو يمجسانه لماذا لم يذكر الرسول ﷺ الإسلام في هذا الحديث؟","title":"ماهي الفطرة التي يولد المولود عليها؟","answer":"الجواب:  جاء في الحديث الصحيح: ما من مولود يولد إلا على الفطرة وفي بعضها: إلا على هذه الملة ملة الإسلام، جاء هذا وهذا، معنى الفطرة يعني على الإسلام، فإذا مات صغيرًا؛ فهو على الإسلام، فأولاد المسلمين كلهم مع آبائهم في الجنة بإجماع أهل السنة والجماعة، أن أولاد المسلمين من أهل الجنة على العموم، وهكذا أولاد الكفار إذا ماتوا صغارًا، الصحيح أنهم من أهل الجنة، وقال بعض أهل العلم: إنهم يمتحنون يوم القيامة، يختبرون، فمن أطاع؛ دخل الجنة، ومن عصى؛ دخل النار، ولكن الأرجح أنهم من أهل الجنة؛ لقوله ﷺ: ما من مولود يولد إلا على الفطرة، فأبواه يهودانه، أو ينصرانه، أو يمجسانه وهذا ما هوده أبواه، ولا مجساه، ولا نصراه؛ ولأنه ثبت عنه ﷺ أنه رأى مع إبراهيم في روضة من رياض الجنة حين عرج به إلى السماء رأى معه أولاد المسلمين، وأولاد المشركين في الروضة، في روضة الجنة.  فالمقصود: أن الصحيح أن المولود الذي يموت قبل البلوغ أنه يموت على الفطرة، على فطرة الإسلام، وأنه لا يكون مع أهله في النار إذا كانوا كفارًا، بل هو مع المسلمين، نعم. المقدم: بارك الله فيكم إذًا أولاد المسلمين من باب أولى سماحة الشيخ؟ الشيخ: من باب أولى نعم، بإجماع المسلمين .... المسلمين بإجماع أهل السنة أنهم من أهل الجنة إذا ماتوا قبل البلوغ، أما الخلاف في أولاد الكفار، أولاد اليهود والنصارى والكفار إذا ماتوا صغارًا، هل يكون مع آبائه في النار على أقوال: أرجحها وأحسنها أنهم من أهل الجنة ... وقد سئل النبي ﷺ عنهم فقال: الله أعلم بما كانوا عاملين لكن دلت الأحاديث الصحيحة على أنهم من أهل الفطرة، وأنهم من أهل الجنة، وأنهم مع إبراهيم في الجنة لما رآه -عليه الصلاة والسلام- حين عرج به. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10633/ماهي-الفطرة-التي-يولد-المولود-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40302.mp3","categories":["الإسلام والإيمان"]},{"id":13168,"question":"السائلة التي رمزت لاسمها؟ (م) تقول: أرجو توضيح معنى الإسلام؟","title":"توضيح معنى الإسلام","answer":"الجواب:  الإسلام معناه: الاستسلام لله بالتوحيد، والانقياد له بالطاعة ذلًا وخضوعًا، هذا معنى الإسلام، يقال: أسلم فلان لفلان، أي: ذل له، وانقاد له، وأعطاه مطلوبه، فالإسلام معناه: ذل لله، وانقياد لله بتوحيده، والإخلاص له، وطاعة أوامره، وترك نواهيه، هذا هو الإسلام، قال تعالى: إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ [آل عمران:19]، وسمي المسلم مسلمًا؛ لأنه منقاد لله، ذليل مطيع له سبحانه في فعل ما أمر، وترك ما نهى. ويطلق الإسلام على جميع ما أمر الله به ورسوله من صلاة وصوم وحج وإيمان وغير ذلك، كله يسمى إسلام، كما قال الله : إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ [آل عمران:19] وقال تعالى: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3] وقال سبحانه: وَمَنْ يَبْتَغِ غَيْرَ الإِسْلامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [آل عمران:85].  فالمسلم هو المنقاد لأمر الله قولًا وعملًا وعقيدة، والإسلام: هو الانقياد لأمر الله، والتسليم لأمر الله، والذل لأمر الله من جميع الوجوه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11423/توضيح-معنى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51104.mp3","categories":["الإسلام والإيمان"]},{"id":13284,"question":"يقول: ما كيفية زيادة الإيمان سماحة الشيخ؟","title":"كيفية زيادة الإيمان ونقصانه","answer":"الجواب:  الإيمان يزيد وينقص، يزيد بالطاعات وينقص بالمعاصي، فإذا صلى الصلوات الخمس، وحافظ عليها، وصلى مع هذه الرواتب؛ زاد إيمانه، وإذا أخل بالرواتب؛ نقص إيمانه، أو أخل بالزكاة نقص إيمانه، أو بالصوم؛ نقص إيمانه، أو بصلة الرحم؛ نقص إيمانه.. وهكذا. بالمعصية ينقص الإيمان، وبالطاعات يزيد الإيمان، يزيد في صحائف أعماله، وفي ميزانه، وعند ربه  كلما أدى طاعة؛ زاد الإيمان، وكلما أدى معصية؛ نقص الإيمان، وكلما ترك شيئًا من الواجبات؛ نقص الإيمان، وهكذا.. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11569/كيفية-زيادة-الايمان-ونقصانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50915.mp3","categories":["الإسلام والإيمان"]},{"id":13503,"question":"السائل من الجزائر له سؤال آخر يقول سماحة الشيخ: هل يتنافى العلم مع الإيمان؟","title":"بيان عدم تنافي العلم مع الإيمان","answer":"الجواب: ما يتنافى العلم مع الإيمان، قال الله -جل وعلا-: وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالإِيمَانَ لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَى يَوْمِ الْبَعْثِ [الروم:56] فالعلم والإيمان قرينان، فلا يتم الإيمان إلا عن علم، الإيمان لا بد يكون عن علم، الإيمان بالله وبرسوله وبملائكته وكتبه ورسله واليوم الآخر وبالقدر خيره وشره، والإيمان بما أخبر الله به عن الآخرة والجنة والنار والحساب والجزاء وعما يكون في آخر الزمان إلى غير ذلك، لا بد من العلم والإيمان. فلا بد أن يؤمن بالله عن بصيرة، عن علم، يؤمن بأن الله خلقه، وأن الله رازقه، وأن الله هو المعبود بالحق، وأن الله هو الكامل في ذاته وأسمائه وصفاته وأفعاله، لا شبيه له، ولا شريك له، وعلى العبد أن يؤمن بأن الله فوق العرش، فوق جميع الخلق، في العلو، ليس في السفل، الله سبحانه فوق العرش، فوق جميع الخلق كما قال -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] في سبعة مواضع، وقال سبحانه: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] وقال سبحانه: وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] وقال -جل وعلا-: تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ [المعارج:4] وقال سبحانه: إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ [فاطر:10] فهو في العلو -جل وعلا- فوق العرش، فيجب الإيمان بذلك، ومن قال: إن الله في كل مكان؛ فقد كفر، وكذب الله، وكذب رسله. فيجب الإيمان بأنه سبحانه يتكلم إذا شاء، وأنه يرضى ويغضب، وأنه السميع العليم، وأنه القدير، وأنه على كل شيء قدير، وأنه المعطي المانع .. الخلاق الرزاق، وأنه على كل شيء قدير، وأنه سبحانه العالم بأحوال عباده، وأنه المستحق لأن يعبد، فلا يستحق العبادة سواه، وأنه الخلاق العليم، وأنه رب العالمين. فيجب على العباد أن يؤمنوا بهذا، وأن تكون أعمالهم عن علم عن بصيرة، فهو يصلي عن إيمان بأن الله المعبود الحق، وأنه فوق العرش، يصوم كذلك .. يزكي كذلك عن إيمان، وعن علم بأن ربه فوق العرش، وأن ربه هو العالي فوق خلقه، وأنه الكامل في ذاته وأسمائه وصفاته، لا شبيه له، ولا كفو له، ولا ند له، فهو يصلي على هذا الإيمان -عن علم- ويصوم ويزكي ويبر والديه ويجاهد عن هذا الإيمان، عن إيمانه بالله ورسوله، عن إيمانه بأن معبوده الحق فوق العرش .. فوق جميع الخلق، وأنه العالي فوق جميع الخلق، ومن قال: إن الله في كل مكان، وأنه في الأرض، وأنه ليس فوق العرش؛ فهذا مكذب لله، ومكذب لرسوله، فيكون بهذا كافرًا، نسأل الله العافية، لا حول ولا قوة إلا بالله! المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11814/بيان-عدم-تنافي-العلم-مع-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53103.mp3","categories":["الإسلام والإيمان"]},{"id":14554,"question":"هذا السائل من السودان رمز لاسمه بـ (أ. أ) يقول في هذا  ما هو الفرق بين النبي والرسول؟ وما هي فائدة علم النبي للبشر؟","title":"الفرق بين النبي والرسول","answer":"الجواب: المشهور أن النبي هو الذي يوحى إليه بشرع لنفسه، يعمل بنفسه، ولا يؤمر بالتبليغ، والرسول الذي يؤمر بالتبليغ مثل النبي ﷺ لما قيل له: اِقْرَأ [العلق:1ٍٍ] هذا نبي، فلما قيل له: قُمْ فَأَنْذِر [المدثر:2] صار رسولًا نبيًا جميعًا، فالرسول هو الذي يؤمر بالتبليغ، يوحى إليه ويؤمر بتبليغ الناس ودعوتهم كمحمد ﷺ وموسى وعيسى وداود وسليمان ونوح ونحوهم. والنبي هو الذي يوحى إليه بشرع، ولكن لا يؤمر بالتبليغ، ككثير من أنبياء بني إسرائيل أوحي إليهم، ولم يؤمروا بالتبليغ، بل لأنفسهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13051/الفرق-بين-النبي-والرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55514.mp3","categories":["الإسلام والإيمان","مسائل متفرقة في العقيدة"]},{"id":15957,"question":"يسأل ويقول: ما معنى الإسلام؟أثابكم الله.","title":"معنى الإسلام","answer":"الجواب: الإسلام: هو الاستسلام لله، والخضوع له بفعل أوامره، وترك نواهيه، هذا هو الإسلام إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ[آل عمران:19] الإسلام يعني: الانقياد والذل لله بتوحيده والإخلاص له، وطاعة أوامره، وترك نواهيه، هذا هو الإسلام، ومن ذلك: أداء الصلاة، أداء الزكاة، صوم رمضان، حج البيت، بر الوالدين، صلة الرحم، ترك المعاصي كلها داخلة في الإسلام، وسمي دين الله إسلامًا؛ لأنه ذل لله، وانقياد لطاعته، وترك لمعصيته، فلهذا قيل له: الإسلام، يقال: أسلم فلان لفلان يعني: ذل له وانقاد لأوامره، فالإسلام: هو الانقياد لأوامر الله، والطاعة لأوامر الله، عن خشوع، وعن ذل، وعن انكسار، وعن رغبة فيما عند الله مرضاة له ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14565/معنى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74612.mp3","categories":["الإسلام والإيمان"]},{"id":17640,"question":"أخونا السائل إبراهيم أبو حامد جزاه الله خيرًا أرسل بمجموعة من الأسئلة يقول في العقيدة: سماحة الشيخ! هل يجب الإيمان بجميع الملائكة والمرسلين؟ وما حكم من لم يحب بعضهم؟","title":"هل يجب الإيمان بجميع الملائكة والمرسلين؟","answer":"الجواب: يجب على كل مؤمن أن يؤمن بالله وملائكته وكتبه ورسله، هذا من أصول الإيمان، لابد أن يؤمن بالملائكة وإن لم يعرف أسماءهم، يعني: يؤمن بمن سمي كـجبرائيل وميكائيل وإسرافيل، ويؤمن بالجميع وإن لم يعرف أسماءهم، يؤمن بأن لله ملائكة أخبر عنهم  في طاعته وتنفيذ أوامره، من جبرائيل وميكائيل وحملة العرش وغيرهم. ويؤمن بالرسل جميعًا وإن لم يعرف أسماءهم، يؤمن بأن الله أرسل رسلًا وأنهم بلغوا الرسالات، ومن سماه الله يؤمن به: كـنوح و إبراهيم و موسى و عيسى و داود و سليمان ، من سماه الله آمن به، ومن لم يسم يؤمن بأن لله رسلاً وإن لم يعرف أسماءهم، كما يؤمن بخاتمهم محمد ﷺ، وأنه رسول الله إلى الجميع إلى جميع الثقلين، وأنه خاتم الأنبياء، لابد من الإيمان بهذا، من لم يؤمن بهذا فهو كافر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/16562/هل-يجب-الايمان-بجميع-الملاىكة-والمرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59418.mp3","categories":["الإسلام والإيمان"]},{"id":17753,"question":"في آخر أسئلة السائل أبو أحمد يقول: كيف يعرف المسلم مقدار إيمانه؟","title":"كيفية معرفة المسلم مقدار إيمانه","answer":"الجواب: على قدر خوفه من الله وتعظيمه لله، ومسارعته لما أوجب الله، وتركه لما حرم الله؛ يدل هذا على قوة الإيمان، وإذا تساهل بالمعاصي فهذا يدل على ضعف الإيمان.\nفالإيمان القوي هو الذي يتضمن خوف الله ومراقبته والمسارعة إلى ما أوجب والحذر مما حرم، هذا دليل على قوة الإيمان، وأن صاحبه على خير.\nأما إذا كان يتساهل بالمعاصي، ترك الصلاة في الجماعة، عقوق الوالدين، الغيبة، النميمة، تعاطي الربا؛ هذا يدل على ضعف الإيمان وقلة الإيمان، ولا حول ولا قوة إلا بالله.\nالمقدم: بارك الله فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16724/كيفية-معرفة-المسلم-مقدار-ايمانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59615.mp3","categories":["الإسلام والإيمان"]},{"id":17959,"question":"مع مطلع هذه الحلقة نعود إلى رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، عرضنا بعض أسئلةٍ له في حلقةٍ مضت، وفي هذه الحلقة يسأل سماحتكم -شيخ عبد العزيز - فيقول: ما هو السبيل إلى تقوية الإيمان بالله واليوم الآخر؟ جزاكم الله خيرًا.","title":"سبل تقوية الإيمان بالله واليوم الآخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد:\nهذا سؤال مهم، وجدير بالعناية، وهو: ما هو السبيل إلى تقوية الإيمان بالله، واليوم الآخر؟\nالسبيل إلى ذلك من جهاتٍ كثيرة، أولًا: من جهة تدبر القرآن الكريم، والعناية بقراءته، والإكثار من ذلك، لما فيه من القصص العظيم عن الآخرة، والجنة، والنار، وعن أسماء الله وصفاته، وعن أخبار الرسل عليهم الصلاة والسلام، وأممهم، فمن تدبر القرآن؛ قوي إيمانه، واستقام له دينه، إذا وفقه الله، فالنصيحة لكل مؤمن، ولكل مؤمنة العناية بالقرآن، والإكثار من تلاوته، ومن تدبر معانيه، والإقبال على ذلك بنيةٍ صالحة، وقصد صالح لقصد العلم بالله، وقوة الإيمان بالله، ولقصد الإيمان بالآخرة، وقوة ذلك، ولقصد العمل بما يرضي الله، ويقرب لديه، وينفع في الآخرة، ويكون سببًا للنجاة، والسعادة في الآخرة. ومن أسباب ذلك أيضًا؛ العناية بالأحاديث، وأخلاق النبي ﷺ، وأخلاق الصحابة والأخيار، كونه يسمع الأحاديث، يسمع سيرة النبي ﷺ، وأعماله، وأعمال الصحابة، ونشاطهم في الخير، وخوفهم من الله ، حتى يتأسى بهم، يتأسى بالأخيار، يعمل كأعمالهم، ويجتهد في ذلك.\nومن أسباب تقوية الإيمان أيضًا؛ أن يحاسب نفسه، ويتذكر، الموت يأتي بغتة، ماذا عمل، ماذا قدم لآخرته، حتى يعد العدة، قبل أن يهجم عليه الأجل، فإن محاسبة النفس، والنظر فيما أعده العبد للآخرة؛ مما يقوي إيمانه، ومما يعينه على طاعة الله ورسوله، ومما يعينه على البدار بالتوبة إلى الله من سيئات أعماله، وتقصيره، كل هذا من أسباب قوة الإيمان، ومن أسباب ذكر الآخرة، والاستعداد لها.\nومن ذلك أمر رابع أيضًا، وهو صحبة الأخيار، كونه يصحبهم، ويجالسهم، فيستفيد من أخلاقهم، وعلمهم، ويذكرونه بالآخرة، ويعينونه على ذلك، هذا من الأسباب.\nهكذا أيضًا أمر خامس، وهو حضور حلقات العلم، يلتمسها، ويحضرها، ويستفيد منها، وكذلك يصغي عند سماع الخطب، خطب الجمعة، وغيرها من الخطب النافعة، ومن إذاعة القرآن، يستمع إلى القرآن الكريم، يستمع المواعظ، والندوات المفيدة، حتى يستفيد من ذلك، وحتى يرق قلبه، ويقوى إيمانه، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16980/سبل-تقوية-الايمان-بالله-واليوم-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72901.mp3","categories":["الإسلام والإيمان"]},{"id":18375,"question":"يسأل أخونا ويقول: ما الفرق بين الإيمان والإسلام؟","title":"الفرق بين الإيمان والإسلام","answer":"الجواب: الإيمان هو الإسلام، والإسلام هو الإيمان عند الإطلاق؛ لأن الإيمان تصديق القلوب وكل ما يتعلق بالإسلام من قول أو عمل، والإسلام كذلك هو الانقياد لله والخضوع له بتوحيده والإخلاص له وطاعة أوامره وترك نواهيه؛ فإذا أطلق أحدهما شمل الآخر، كما قال : إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ[آل عمران:19]، يعني: والإيمان داخل في ذلك. أما إذا جمعا فإن الإسلام هو الأعمال الظاهرة، والإيمان هو الأعمال الباطنة، إذا جمع بينهما كما في حديث جبريل أنه سأل النبي ﷺ عن الإسلام والإيمان، فسر له النبي ﷺ الإسلام بالأمور الظاهرة كالشهادتين والصلاة والزكاة والصيام والحج، وفسر له الإيمان بالأمور الباطنة قال: أن تؤمن بالله وملائكته وكتبه ورسله، وباليوم الآخر وبالقدر خيره وشره. هذا هو الفرق بينهما عند الاجتماع يكون الإسلام المراد به الأعمال الظاهرة، والإيمان الأعمال الباطنة، وإن أطلق بأحدهما يدخل فيه الآخر، وهكذا قوله ﷺ: الإيمان بضع وسبعون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان، .....: الإيمان بضع وسبعون شعبة، هذا يدخل فيه الإسلام، ولهذا ذكر: أفضل الإيمان لا إله إلا الله، وهي أصل الإسلام، فدل ذلك على أن الإيمان إذا أطلق دخل فيه الإسلام، وهكذا إذا أطلق الإسلام دخل فيه الإيمان عند أهل السنة . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17447/الفرق-بين-الايمان-والاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86204.mp3","categories":["الإسلام والإيمان"]},{"id":18441,"question":"هل المسلم الذي يحافظ على الصلوات الخمس، وجميع الواجبات، ومنتهي عما نهى الله عنه؛ يعتبر ضعيف الإيمان إذا لم يكن حافظًا للقرآن بأكمله؟","title":"مدى تأثير عدم حفظ القرآن على الإيمان","answer":"الجواب: يعتبر كامل الإيمان ولو ما حفظ القرآن، يعتبر إذا أدى الواجبات وترك المحارم هذا كامل الإيمان، وإذا كان يسابق إلى المزيد من الخيرات من التطوعات صار من السابقين إلى الخيرات، ولو كان ما حفظ القرآن، حفظ القرآن ما هو بواجب، فإذا كان يعمل بالقرآن، وينفذ أوامر القرآن؛ فالحمد لله، إن تيسر حفظه فهو سنة، وإلا ما هو لازم، الحمد لله.نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17526/مدى-تاثير-عدم-حفظ-القران-على-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78504.mp3","categories":["الإسلام والإيمان"]},{"id":19006,"question":"من المستمع: فتوح صديق مصري الجنسية، رسالة وضمنها بعض الأسئلة، في أحد أسئلته يقول: ما الفرق بين الإيمان والإسلام؟ جزاكم الله خيرًا.","title":"الفرق بين الإيمان والإسلام","answer":"الجواب: الإيمان والإسلام إذا اجتمعا صار بينهما فرق في آية، أو حديث، وإذا انفرد أحدهما عن الآخر دخل فيه الآخر. ففي قوله : إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ[آل عمران:19] يدخل فيه الإيمان؛ لأن الإسلام إذا أطلق هو الإيمان بالله، وملائكته، وكتبه، ورسوله، واليوم الآخر، وبالقدر خيره وشره، وهو أيضًا الشهادتان: شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، وهو أيضًا يدخل فيه الجهاد، والأمر بالمعروف والنهي عن المنكر، والدعوة إلى الله، وصدق الحديث، وإكرام الضيف، وإكرام الجار، وبر الوالدين، وصلة الرحم.. وغير هذا مما أمر الله به ورسوله، ويدخل في الإسلام أيضًا ترك ما نهى الله عنه ورسوله، ويدخل في الإسلام أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك. يعني: مرتبة الإحسان هذا عند الإطلاق إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ[آل عمران:19] وهكذا قوله سبحانه: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا[المائدة:3] يدخل فيه الإيمان، والإحسان عند الإطلاق، وهكذا قوله جل وعلا: وَمَنْ يَبْتَغِ غَيْرَ الإِسْلامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ[آل عمران:85] يدخل فيه الإيمان، والإحسان، ويدخل فيه كل ما أمر الله به ورسوله، وترك كل ما نهى الله عنه ورسوله، كله داخل في الإسلام عند الإطلاق. وهكذا الإيمان إذا أطلق دخل فيه جميع الأوامر، وترك جميع النواهي، إذا جاء مطلقًا مثل: يَا أَيُّهَا الَّذِينَ آمَنُوا آمِنُوا بِاللَّهِ وَرَسُولِهِ[النساء:136] ومثل قوله جل وعلا: فَآمِنُوا بِاللَّهِ وَرَسُولِهِ وَالنُّورِ الَّذِي أَنزَلْنَا[التغابن:8] وهكذا ما أشبه من الآيات يدخل في ذلك جميع ما أمر الله به ورسوله، وترك ما نهى الله عنه ورسوله، وهكذا الحديث الصحيح يقول النبي ﷺ: الإيمان بضع وسبعون شعبة، فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان أخرجه البخاري و مسلم في الصحيحين، وهذا لفظ مسلم رحمه الله، فقوله: الإيمان بضع وسبعون شعبة، وفي اللفظ الآخر: بضع وستون شعبة يدخل فيه شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، والجهاد، والأمر بالمعروف، والنهي عن المنكر، وترك جميع المعاصي، ويدخل فيه الإيمان بالله، وملائكته، وكتبه، ورسوله، واليوم الآخر، وبالقدر خيره وشره. يدخل فيه الإيمان بكل ما أخبر الله به ورسوله عما كان فيما مضى من الزمان، وعما يأتي في آخر الزمان. ويدخل فيه ما أخبر الله به عن القيامة، والجنة والنار، والحساب والجزاء، كله داخل في قوله: الإيمان بضع وسبعون شعبة. أما إذا اجتمعا فالإسلام هو الأعمال الظاهرة، والإيمان هو الأعمال الباطنة، كما في سؤال جبريل للنبي ﷺ عن الإسلام والإيمان فإن جبرائيل أتى النبي ﷺ في يوم من الأيام وهو جالس بين أصحابه في صورة إنسان غير معروف، وسأله عن الإسلام، والإيمان، والإحسان، فقال له النبي ﷺ: الإسلام أن تشهد أن لا إله إلا الله وأن محمدًا رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلًا، قال: أخبرني عن الإيمان، قال: الإيمان أن تؤمن بالله، وملائكته، وكتبه، ورسوله، واليوم الآخر، وبالقدر خيره وشره، قال: أخبرني عن الإحسان، قال: أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك . وكان يصدقه كل ما أخبر به قال: صدقت، يصدقه جبرائيل عليه الصلاة والسلام، فالمقصود أنه أخبره عن الإسلام بالأعمال الظاهرة، وعن الإيمان بالأعمال القلبية، وعن الإحسان بشيء خاص من أعمال القلب وهو أن تعبد الله كأنك تراه تشاهده، فإن لم تكن تراه فإنه يراك يعني: على اعتقاد واستحضار أنه يراك، ويشاهدك ، وهذا أعلى مراتب الإسلام، والإيمان، أن تعبد الله كأنك تراه. وبهذا تعلم ويعلم كل من سمع هذه الكلمة الفرق بين الإيمان، والإسلام، والإحسان عند الاجتماع.\nوأن الإسلام إذا انفرد دخلت فيه أعمال الإيمان، والإحسان، والإيمان إذا انفرد دخل فيه أعمال الإسلام، والإحسان. أما إذا اجتمعت الثلاثة فالإسلام هو الأعمال الظاهرة، والإيمان هو أعمال القلب الباطنة، والإحسان هو عمل خاص من أعمال القلب وهو أن تعبد الله كأنك تراه الحديث، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18166/الفرق-بين-الايمان-والاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79507.mp3","categories":["الإسلام والإيمان"]},{"id":19257,"question":"رسالة طلب مرسلها أن نعرضها مرتين في هذا البرنامج، وسنستجيب لطلبه جزاه الله وإياكم خيرًا، يقول المرسل عصام بكري مصطفى يسأل فيقول: ما معنى الكفر بالطاغوت؟ جزاكم الله خيرًا.","title":"معنى الكفر بالطاغوت","answer":"الجواب: معناه البراءة منه واعتقاد بطلانه، قال الله سبحانه: فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى [البقرة:256]، معنى الطاغوت المعبود من دون الله، يعني: يتبرأ من عبادة غير الله، عبادة الأوثان والأصنام والجن يتبرأ منها ويعتقد بطلانها، ويؤمن بأن المعبود الحق هو الله وحده  فمن لم يؤمن بهذا فليس بمسلم، لا بد أن يؤمن بأن الله هو المستحق للعبادة، وأن عبادة الطواغيت عبادة الجن عبادة الأصنام عبادة من دعا إلى عبادة نفسه كل هذا باطل، لا بد أن يتبرأ منها، والطواغيت: كل من عبد من دون الله وهو راضٍ، وهكذا الأصنام تسمى طواغيت والأشجار والأحجار المعبودة تسمى طواغيت، أما الأولياء والأنبياء والملائكة فليسوا طواغيت أعني الطاغوت الذي دعا إلى عبادته، الطاغوت الذي دعا إلى الشرك بالله وعبادته، من الشياطين: شياطين الإنس أو الجن هم الطواغيت. أما الأولياء المؤمنون يبرءون إلى الله منهم، ما يرضون بأن يعبدوا من دون الله، هكذا الأنبياء هكذا الملائكة وهكذا الجن المؤمنون ما يرضون، فالطاغوت: هو الذي يدعو إلى عبادة غير الله، أو يرضى بها كـفرعون وأتباعه. فالبراءة من ذلك معناه البراءة من عبادة غير الله، واعتقاد بطلانه يعني أن تبرأ من عبادة غير الله وأن تعتقد بطلان ذلك، وأن العبادة الحق لله وحده  كما قال  في كتابه العظيم في سورة الحج: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18450/معنى-الكفر-بالطاغوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73903.mp3","categories":["الإسلام والإيمان"]},{"id":19378,"question":"يسأل أخونا سؤال آخر فيقول: هل مجرد التلفظ بالشهادتين يعصم الإنسان، ويعصم دمه وماله؟ وإذا انتفى عنه العلم بمدلول لا إله إلا الله وهو يرددها ليل نهار هل تكفيه؟ وهل تدخله الجنة وتنجيه من النار؟","title":"هل مجرد التلفظ بالشهادتين يعصم دم الإنسان وماله؟","answer":"الجواب: لفظ لا إله إلا الله، ولفظ شهادة أن محمدًا رسول الله هاتان الشهادتان هما أصل الدين، هما أساس الملة، فمن أتى بهما وهو لا يقولهما قبل ذلك عصم دمه وماله وحكم بإسلامه. ثم ينظر ويعلم ويفقه؛ فإن قبل الحق واستقام عرف صدقه، وإن أبى واستمر على كفره وشركه وعبادته الأصنام أو الأشجار أو الأحجار أو أصحاب القبور أو استمر على استهزائه بالدين وسبه للدين، أو غير هذا من نواقض الإسلام لم تنفعه هذه الشهادة يكون مرتدًا. فهو يحكم بإسلامه أولًا، ثم بمجيئه بما يخالف الإسلام بما يوجب الردة يحكم بردته، كما قال النبي ﷺ: من بدل دينه فاقتلوه. فالشخص إذا نطق بالشهادتين وهو لا ينطق بهما سابقًا حكم بإسلامه كما كان في عهد النبي ﷺ وكما بينه الرسول ﷺ في الأحاديث الصحيحة في حديث أسامة وفي غيره حديث ابن عمر وحديث أبي هريرة وغير ذلك يقول عليه الصلاة والسلام: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحقها وفي اللفظ الآخر إلا بحق الإسلام. فالمقصود أنه إذا أتى بهذه الشهادة فإنه يعصم دمه وماله إذا كان لم يأت بهما قبل ذلك، ثم ينظر في أمره فإن استقام على دين الله صار له حكم المسلمين، وإن أبى وبقي على كفره وضلاله لم تنفعه الشهادة بمجرد القول، فالمنافقون يقولونها وهم في الدرك الأسفل من النار؛ لأنهم قالوها ولم يعملوا بها بل كفروا بها، وكذبوا الله ورسوله، أو شكوا في دين الله. وهكذا الذين قال الله فيهم: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ [التوبة:65] لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:66] هم أناس أظهروا الإسلام وشاركوا المسلمين في أعمالهم، ولكن ظهر منهم الاستهزاء بالرسول ﷺ وبالإسلام فلهذا أنزل الله في حقهم قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ  ۝  لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:66]. وقد أجمع العلماء على أن من أتى بناقض من نواقض الإسلام يحكم عليه بذلك الناقض، وإن قال: أشهد أن لا إله إلا الله وأن محمدًا رسول الله وإن صلى وصام؛ لأن هذه الشهادة إنما تنفع إذا أدي حقها، أما إذا ضيع حقها لم تنفع قائلها، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18599/هل-مجرد-التلفظ-بالشهادتين-يعصم-دم-الانسان-وماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93408.mp3","categories":["الإسلام والإيمان"]},{"id":19475,"question":"أولى رسائل هذه الحلقة: رسالة وصلت إلينا من إحدى الأخوات المستمعات تقول: المرسلة (أ. م. أ): أختنا لها بعض الأسئلة فتسأل - مثلًا - وتقول: هل يحكم بالإسلام لمن أظهر شيئًا من أمور الإسلام، أم يتوقف إلى أن تعرف عقيدته؟","title":"وجوب الحكم بالإسلام لمن أظهر ما يدل على إسلامه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فالواجب هو الحكم بالإسلام لمن أظهر ما يدل على إسلامه كالشهادتين: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وكصلاته مع المسلمين؛ فإن هذا يدل على أنه مسلم حتى يتبين ما يخالف ذلك، فإذا تبين منه ما يخالف ذلك وجبت نصيحته، ووجب إرشاده، ودلالته على ما قد يخفى عليه، فإن ظهر منه الردة عن الإسلام وما يحكم به عليه بذلك، فإن على ولي الأمر أن يستتيبه، فإن تاب وإلا وجب أن يقتل لقول النبي ﷺ: من بدل دينه فاقتلوه رواه البخاري في صحيحه. والخلاصة: أن الواجب حمل من أظهر الإسلام على الإسلام، وتوجيهه إلى الخير، وتعليمه ما جهل، وإرشاده إلى ما قد يخفى عليه حتى يتبين منه ما يدل على كفره، وضلاله؛ فيعامل كما يعامل غيره من الكفرة المرتدين، نسأل الله السلامة والعافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18721/وجوب-الحكم-بالاسلام-لمن-اظهر-ما-يدل-على-اسلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94501.mp3","categories":["الإسلام والإيمان"]},{"id":19682,"question":"سماحة الشيخ هذا سائل من الرياض يقول: يا سماحة الشيخ ما هي مراتب الدين مع ذكر أركان كل مرتبة؟ جزاكم الله خيرًا.","title":"مراتب الدين وأركان كل مرتبة","answer":"الجواب: مراتبه ثلاث: الإسلام، والإيمان، والإحسان، كما بيَّنه النبي ﷺ. فالمرتبة الأولى: الإسلام المرتبة العامة، وأركانها خمسة: شهادة أن لا إله إلا الله، وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، وكل عمل مما شرعه الله داخل في الإسلام. المرتبة الثانية: الإيمان وأركانها ستة: أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وبالقدر خيره وشره. المرتبة الثالثة: الإحسان وهو ركن واحد ومعناه أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك.\nوجميع الأعمال الصالحة داخلة في الإسلام، والإيمان، فإذا جمع المؤمن بين الأعمال كلها الظاهرة والباطنة صار مسلمًا مؤمنًا، وإذا عبد الله كأنه يراه فإن لم يكن يراه فإنه يراه صار مسلمًا مؤمنًا محسنًا، نسأل الله للجميع التوفيق. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/18974/مراتب-الدين-واركان-كل-مرتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95035.mp3","categories":["الإسلام والإيمان"]}]
